const STORIES64={"en":[{"ref":"s1","grade":0,"q":[["Where did the cat sit?",["On the cap","In a cup","Under a boat"],0],["What did Sam and the cat both do?",["Nap","Swim","Bake"],0]],"art":"book"},{"ref":"k2","grade":0,"q":[["What did Pig find under the lid?",["Figs","A hat","A boat"],0],["How did Pig reach the surprise?",["By digging","By flying","By painting"],0]],"art":"book"},{"ref":"k3","grade":0,"q":[["What did the dog hop onto?",["A log","A roof","A chair"],0],["Why was the dog no longer hot?",["It got wet","It put on a coat","It ate a leaf"],0]],"art":"book"},{"ref":"k4","grade":0,"q":[["Where was the bug safe?",["In the rug","On the roof","In a cup"],0],["Could the pup get the bug?",["No","Yes, straight away","Only after flying"],0]],"art":"book"},{"ref":"s2","grade":1,"q":[["Where did Beth and Chad take the ship?",["To the pond","To the roof","To the kitchen"],0],["Why did they cheer?",["The ship floated","The shed fell","Lunch vanished"],0]],"art":"book"},{"ref":"g1a","grade":1,"q":[["What made the pecking sound?",["A woodpecker","A clock","A duck"],0],["What did the bird find to eat?",["A bug","A spoon","A shoe"],0]],"art":"book"},{"ref":"g1b","grade":1,"q":[["What did Frog lift?",["A twig","A house","A boat"],0],["What does Frog learn about strength?",["It can be shown by what you do","Only big animals are strong","It means never resting"],0]],"art":"book"},{"ref":"g1c","grade":1,"q":[["When did Mole come out?",["At night","At lunchtime","At sunrise"],0],["What did Mole compare the moon to?",["A white plate","A green kite","A red wheel"],0]],"art":"book"},{"ref":"s3","grade":1,"q":[["What did Jade use to make the kite?",["A green bag and sticks","A plate and a cup","A wool blanket"],0],["What helped the kite fly?",["The wind","A hidden engine","A bird carrying it"],0]],"art":"book"},{"ref":"g2a","grade":2,"q":[["Why did Thunder like the roof opening?",["He could see the stars","It held his food","It stopped the moon"],0],["What did Marta paint inside?",["Stars","Boats","Spoons"],0]],"art":"book"},{"ref":"g2b","grade":2,"q":[["Who had the spoon?",["A crow","Grandma's cat","A frog"],0],["How did Lou get it back?",["Trading a foil ball","Chasing the moon","Buying a new roof"],0]],"art":"book"},{"ref":"g2c","grade":2,"q":[["Why did the snowball become large?",["It gathered snow as it rolled","It was full of air","It was made of bread"],0],["What did Ben and his sister make with it?",["A snowman's body","A bathtub","A basketball"],0]],"art":"book"},{"ref":"s4","grade":2,"q":[["What filled the low garden corner?",["Rainwater","Sand","Books"],0],["What did the new plants provide?",["Homes and shade for small creatures","A dry roof","A place for cars"],0]],"art":"book"},{"ref":"s5","grade":3,"q":[["What put out the lantern?",["A gust of wind","Tomas's drawing","The river"],0],["What helped Marisol continue?",["A neighbor relit it","She left Tomas behind","She bought a car"],0]],"art":"lamp"},{"ref":"g3a","grade":3,"q":[["What changed when Bolt tried again?",["He moved carefully, step by step","He rushed faster","He stopped looking"],0],["What did Bolt carry without cracking?",["Eggs","Stones","Letters"],0]],"art":"book"},{"ref":"g3b","grade":3,"q":[["How do sperm whales communicate in this text?",["Patterns of clicks","Written notes","Human words"],0],["What are scientists trying to do?",["Understand the signals","Teach whales to write","Stop every sound"],0]],"art":"book"},{"ref":"g3c","grade":3,"q":[["What did Mia find at the marked place?",["An old carving and date","A chest of gold","A lost bicycle"],0],["How did she respect the place?",["Taking a picture and leaving it untouched","Carrying the rock away","Adding a new carving"],0]],"art":"book"},{"ref":"s6","grade":4,"q":[["What is mycelium?",["A web of fungal threads","A kind of bird","A tree's flower"],0],["What can trees give the fungus in the exchange?",["Sugar","Pebbles","Metal"],0]],"art":"book"},{"ref":"s8","grade":4,"q":[["Where were the missing socks?",["In a pipe behind the machine","In every neighbor's pocket","On the roof"],0],["What did Theo do with the found socks?",["Displayed them for owners to claim","Threw them all away","Sold them without asking"],0]],"art":"book"},{"ref":"s9","grade":4,"q":[["What can damage early blossoms?",["A hard frost","A picture of fruit","A warm blanket"],0],["Does one empty harvest prove the tree is dead?",["No","Yes, always","Only if it has green leaves"],0]],"art":"book"},{"ref":"s10","grade":4,"q":[["Why did Lucia think the radio mattered?",["Grandpa still cared for it","It was brand new","It was made of gold"],0],["Who helped her with the repair?",["A knowledgeable neighbor","Nobody","A baby"],0]],"art":"book"},{"ref":"s11","grade":4,"q":[["What kind of plant is bamboo?",["A grass","A moss","A stone"],0],["Why must building bamboo be prepared carefully?",["Moisture and insects can weaken it","It turns into metal","It never changes"],0]],"art":"book"},{"ref":"g4a","grade":4,"q":[["Why did Amara pass to Jonah?",["He was open and she had noticed his effort","She wanted to lose","He had never practiced"],0],["What happened after his kick?",["He scored","The ball became a bird","The game began again"],0]],"art":"book"},{"ref":"g4b","grade":4,"q":[["What does a battery do in the solar system?",["Stores energy for later","Makes sunlight","Holds whole sunbeams like sticks"],0],["What produces electricity when light hits the panel?",["Moving electrons","Falling leaves","Turning the roof"],0]],"art":"book"},{"ref":"g4c","grade":4,"q":[["Where did Pip find a useful role?",["At a bakery","Under the sea","In a library freezer"],0],["What is the main idea?",["A difficulty can become useful in the right setting","Fire suits every place","Nobody can learn a new job"],0]],"art":"book"},{"ref":"s7","grade":5,"q":[["What made Nadia's notes useful?",["They recorded repeated careful observations","They listed only guesses","They were all blank"],0],["What did the observatory confirm?",["The smudge was a comet","The shed was a spaceship","Every star had disappeared"],0]],"art":"book"},{"ref":"s12","grade":5,"q":[["How did Priya's map change?",["She added people's names","All the streets moved","It lost every shape"],0],["What changed most for Priya?",["Her connection with the neighborhood","The number of parks","The color of every building"],0]],"art":"book"},{"ref":"s13","grade":5,"q":[["What can alter reflected Wi-Fi patterns?",["Movement in a room","Only a camera lens","A drawing on paper"],0],["What concern does the text raise?",["People's control over information about them","Whether walls have names","Whether everyone owns a telescope"],0]],"art":"book"},{"ref":"s14","grade":5,"q":[["What did families bring to the last stop?",["Books connected with their memories","New buses","Empty shelves"],0],["What did their visit show?",["The bookmobile had lasting importance","Nobody used the books","The route had never existed"],0]],"art":"book"},{"ref":"s15","grade":5,"q":[["Why does a high site help telescopes?",["There is less atmosphere above them","Stars sit on the mountain","The telescope needs snow"],0],["How can shielded lights help?",["Reducing light scattered into the sky","Making every star brighter","Removing all air"],0]],"art":"book"},{"ref":"g5c","grade":5,"q":[["The river remembering is an example of what?",["A poetic image","A literal human brain","A measured river age"],0],["What does the poem invite the reader to carry?",["What they have learned","Every stone in a river","A whole mountain"],0]],"art":"book"},{"ref":"k5","grade":0,"q":[["What was in the box?",["a frog","a sock","a rock"],0],["Who is Dot?",["a fox","a frog","a dog"],0]],"art":"book"},{"ref":"k6","grade":0,"q":[["Where did Gus jump?",["in the mud","in a box","on a log"],0],["How did Gus get clean?",["in the tub","in the rain","with a fox"],0]],"art":"book"},{"ref":"k7","grade":0,"q":[["How many hens?",["ten","two","five"],0],["What color are the hens?",["red","blue","green"],0]],"art":"book"},{"ref":"k8","grade":0,"q":[["What does a seed need?",["rain and sun","a box","a hat"],0],["What did the seed become?",["a flower","a frog","a rock"],0]],"art":"book"},{"ref":"k9","grade":0,"q":[["What did Jen do to feel better?",["took breaths","yelled","ran away"],0],["How did Jen feel at the end?",["glad","mad","sleepy"],0]],"art":"book"},{"ref":"k10","grade":0,"q":[["Does the moon make its own light?",["No","Yes"],0],["The moon is like a…",["mirror","lamp","box"],0]],"art":"book"},{"ref":"k11","grade":0,"q":[["Who could reach the top?",["Dad","the cat","me"],0],["Help is a…",["gift","plum","mess"],0]],"art":"book"},{"ref":"g1x","grade":1,"q":[["What did the plow clear?",["snow","leaves","sand"],0],["What did the big trucks say?",["You are too small","Good job","Go home"],0]],"art":"book"},{"ref":"g1y","grade":1,"q":[["What is the yellow dust called?",["pollen","sugar","sand"],0],["What should you do near a bee?",["be calm","swat it","yell"],0]],"art":"book"},{"ref":"g1z","grade":1,"q":[["What was in the pot first?",["a stone","a carrot","beans"],0],["Who made the feast?",["the whole town","just the boy","nobody"],0]],"art":"book"},{"ref":"g2x","grade":2,"q":[["Where does the tortoise rest in summer?",["in a burrow","in a tree","in a river"],0],["What is its secret?",["knowing when to wait","running fast","flying"],0]],"art":"book"},{"ref":"g2y","grade":2,"q":[["What stopped the clock?",["a pigeon nest","the rain","a cat"],0],["Who helped Mira?",["her grandpa","a baker","the bus driver"],0]],"art":"book"},{"ref":"g2z","grade":2,"q":[["Which planet has rings like a band?",["Saturn","Mars","Earth"],0],["How many planets?",["eight","three","twenty"],0]],"art":"book"},{"ref":"g3x","grade":3,"q":[["How many muffins were missing?",["three","nine","twelve"],0],["Who took the muffins?",["a raccoon","the dog","Leo"],0],["Why was it not the dog?",["dogs cannot climb walls","the dog was full","the dog was outside"],0]],"art":"book"},{"ref":"g3y","grade":3,"q":[["What is the cloud from your breath made of?",["tiny water droplets","smoke","dust"],0],["What is this process called?",["condensation","evaporation","melting"],0]],"art":"book"},{"ref":"g3z","grade":3,"q":[["What animal did they see?",["a mountain goat","a bear","a moose"],0],["How did Ava climb the steep part?",["twenty steps at a time","by running","her uncle carried her"],0]],"art":"book"},{"ref":"g3w","grade":3,"q":[["What stopped working?",["gravity","the lights","the clocks"],0],["What kept kids from floating to space?",["a jump rope on the flag pole","the hamster","a big net"],0]],"art":"book"},{"ref":"g4y","grade":4,"q":[["What is bioluminescence?",["animals making their own light","sunlight in water","a kind of fish food"],0],["How does the anglerfish use light?",["a lure to catch fish","to read","to warm up"],0]],"art":"book"},{"ref":"g4z","grade":4,"q":[["What made the bridge hum?",["wind through the railings","a ghost","trains"],0],["On which days was there no hum?",["calm days","windy days","Mondays"],0]],"art":"book"},{"ref":"g4w","grade":4,"q":[["What trick got them out?",["keep one hand on the wall","follow the scarecrow","climb the corn"],0],["What did they smell near the exit?",["kettle corn","rain","pizza"],0]],"art":"book"},{"ref":"g5x","grade":5,"q":[["What is a transit?",["a planet passing in front of its star","a falling star","a moon eclipse"],0],["What tells scientists the planet's size?",["how much light is blocked","its color","its sound"],0]],"art":"book"},{"ref":"g5y","grade":5,"q":[["Where did Farnsworth get his idea?",["plowing a field","at the movies","in a dream"],0],["What helped prove the idea was his?",["his teacher's drawing","a photo","a letter from NASA"],0]],"art":"book"},{"ref":"g5z","grade":5,"q":[["What made the books fall?",["a leaning shelf shaken by the heater","a ghost","a cat"],0],["What was the cold draft?",["a broken vent","the ghost","an open window"],0],["How did Nadia prove it?",["a test and the security camera","she asked the ghost","she guessed"],0]],"art":"book"},{"ref":"g5w","grade":5,"q":[["What did the robot eat?",["a poster, socks, and cat ears","a sandwich","homework only"],0],["What can the robot NOT sense?",["what is important to Owen","walls","stairs"],0]],"art":"book"},{"id":"d64_en_0_01","grade":0,"t":"A Bed for Pip","art":"pup","text":"Pip is a pup. Pip has a bed.\n\nA red sock is in the bed.\n\nPip can tug it. Pip can hug it.\n\nNow Pip can nap. The sock can nap too.","q":[["Who is Pip?",["A pup","A hen","A bug"],0],["What is in the bed?",["A sock","A cup","A rock"],0]]},{"id":"d64_en_0_02","grade":0,"t":"The Small Cup","art":"cup","text":"Nan has a cup. It is not big.\n\nNan puts it by Dad.\n\nDad puts a sip of milk in it.\n\nNan has a sip. Dad has a sip.\n\nA small cup is just right.","q":[["What does Dad put in the cup?",["Milk","Sand","A leaf"],0],["Is the cup big or small?",["Small","Big","As big as a bed"],0]]},{"id":"d64_en_0_03","grade":0,"t":"A Lamp for Ben","art":"lamp","text":"Ben has a lamp. The lamp is on.\n\nBen has a book. Mom can look.\n\nBen can see a cat in the book.\n\nMom can see it too.\n\nThen the book is shut. Good night, Ben.","q":[["What helps Ben see?",["A lamp","A drum","A sock"],0],["Who looks with Ben?",["Mom","A duck","A bug"],0]]},{"id":"d64_en_0_04","grade":0,"t":"The Red Leaf","art":"leaf","text":"A red leaf fell. It fell by Kit.\n\nKit did not step on it.\n\nKit put it in a big book.\n\nThe leaf can rest flat.\n\nKit can look at it when the snow comes.","q":[["What color is the leaf?",["Red","Blue","Black"],0],["Where does Kit put it?",["In a book","In a cup","In a shoe"],0]]},{"id":"d64_en_0_05","grade":0,"t":"Two on a Mat","art":"cat","text":"A cat sat on a mat.\n\nA pup sat by the cat.\n\nThe mat was small. The pup slid off.\n\nThe cat slid too. Now both can sit.\n\nOne mat. Two soft pals.","q":[["Who sits with the cat?",["A pup","A hen","A fish"],0],["Why does the cat slide over?",["To make room","To get wet","To hide the mat"],0]]},{"id":"d64_en_0_06","grade":0,"t":"The Seed Cup","art":"flower","text":"We put a seed in a cup.\n\nWe put in a bit of soil.\n\nWe give it a sip of water.\n\nWe wait. We look.\n\nA small stem pops up. Hello, little plant!","q":[["What goes into the cup?",["A seed","A shoe","A bell"],0],["What pops up?",["A stem","A fish","A rock"],0]]},{"id":"d64_en_0_07","grade":0,"t":"A Song of Rain","art":"rain","text":"Tap, tap. Rain is on the roof.\n\nTap, tap. I pat my lap.\n\nMom pats her lap too.\n\nThe rain can tap. We can tap.\n\nThen we sit still and hear the rain.","q":[["Where does the rain tap?",["On the roof","In a book","Under a bed"],0],["What do we do at the end?",["Listen","Run out","Ring a bell"],0]]},{"id":"d64_en_0_08","grade":0,"t":"The Lost Bell","art":"bell","text":"Meg has a bell. Where did it go?\n\nMeg can look by the bed. Not there.\n\nMeg can look in the bag. There it is!\n\nDing! Now Meg puts it on the shelf.","q":[["Where is the bell?",["In the bag","By the bed","In the mud"],0],["Where does Meg put it last?",["On the shelf","Under a rug","In a pond"],0]]},{"id":"d64_en_0_09","grade":0,"t":"A Boat at Rest","art":"boat","text":"Dad made a boat from a leaf.\n\nI set it in a bowl.\n\nI give it a soft puff. It can sail!\n\nThe boat bumps the rim.\n\nNow it is at rest. So am I.","q":[["What is the boat made from?",["A leaf","A cup","A sock"],0],["What moves the boat?",["A soft puff","A loud bell","A cat"],0]]},{"id":"d64_en_1_01","grade":1,"t":"The Porch Light","art":"lamp","text":"Nora saw a moth near the porch light. It flew in little loops. She wanted to catch it in her hands.\n\nDad shook his head. \"We can watch without holding it.\"\n\nThey sat on the step. Nora counted four loops. Then Dad turned off the porch light. The moth flew toward the trees. Nora waved with one small finger.","q":[["Why did Nora keep her hands still?",["To watch without catching the moth","To turn into a moth","To hide from Dad"],0],["Where did the moth fly at the end?",["Toward the trees","Into a shoe","Under the step"],0]]},{"id":"d64_en_1_02","grade":1,"t":"The Quiet Delivery","art":"bread","text":"Leo and his aunt baked rolls for their neighbor. They put the warm rolls in a basket. At the door, Leo saw a sign: Baby sleeping.\n\nHe did not ring the bell. His aunt sent a note on her phone. They left the basket by the door and walked away softly.\n\nSoon a message came back: Thank you. We will have a warm breakfast.","q":[["Why did Leo not ring the bell?",["A baby was sleeping","The rolls were cold","He lost the basket"],0],["What did they leave?",["Warm rolls","A toy boat","A lamp"],0]]},{"id":"d64_en_1_03","grade":1,"t":"Moss on the Wall","art":"leaf","text":"A patch of moss grew on a low wall. Mina touched it with one finger. It felt like a tiny green rug.\n\n\"Can we take it home?\" she asked.\n\n\"This wall is its home,\" said her uncle.\n\nMina drew the moss instead. She made green dots with her pencil. At home, her drawing reminded her of the cool, soft wall.","q":[["What did the moss feel like?",["A tiny rug","A sharp stone","A glass cup"],0],["What did Mina take home?",["A drawing","The wall","All the moss"],0]]},{"id":"d64_en_1_04","grade":1,"t":"The Button Boat","art":"boat","text":"Eli made a paper boat. He put a heavy button in it. The boat tipped to one side.\n\nHe moved the button to the middle. Now the boat sat flat in the sink.\n\nHis sister made a soft breeze with a fan made of paper. The boat moved slowly. Eli called it a ship with one round passenger.","q":[["Why did Eli move the button?",["To help the boat sit flat","To make the sink dry","To hide the paper"],0],["What made the breeze?",["A paper fan","The button","A bell"],0]]},{"id":"d64_en_1_05","grade":1,"t":"A Place for Boots","art":"home","text":"Wet boots stood by the door. Water dripped onto the floor. Jo found an old tray in the cupboard.\n\nShe put the boots on the tray. Then she wiped the floor with Dad.\n\nThe next day it rained again. Jo knew just where her boots should go. The little tray saved them from a big puddle indoors.","q":[["What caught the water?",["An old tray","A book","A pillow"],0],["What problem did Jo solve?",["Drips on the floor","A missing hat","A broken clock"],0]]},{"id":"d64_en_1_06","grade":1,"t":"The Library Cushion","art":"book","text":"The blue cushion at the library was big enough for two. Sol sat on one side. A new child stood nearby with a book.\n\nSol moved his bag off the other side. \"This spot is free,\" he said.\n\nThey read different books. They did not need to talk. When it was time to leave, the new child smiled and said, \"See you here next week.\"","q":[["How did Sol make room?",["He moved his bag","He hid the cushion","He closed the library"],0],["Did they have to read the same book?",["No","Yes, every page","Only the cover"],0]]},{"id":"d64_en_1_07","grade":1,"t":"The Bread End","art":"bread","text":"There was one end piece left on the loaf. Ada thought it looked too hard for a sandwich.\n\nGrandma cut it into little cubes. Ada brushed them with oil. Grandma baked them until they were crisp.\n\nAt supper, the cubes floated on their soup. Ada liked the little crunch. The piece that had seemed useless became her favorite part.","q":[["What did the bread become?",["Crisp soup cubes","A new bowl","A paper boat"],0],["Who used the oven?",["Grandma","The cat","Ada alone"],0]]},{"id":"d64_en_1_08","grade":1,"t":"The Slow Snail","art":"snail","text":"A snail crossed the wet path. Ivo wanted to see where it would go. He put his bike on the grass and waited with Mom.\n\nThe snail reached a leaf. It climbed up, slowly and slowly.\n\n\"It is not late for anything,\" Mom said.\n\nIvo took a long breath. They had time to watch one small journey before riding home.","q":[["Why did Ivo stop his bike?",["To watch a snail","To chase a bus","To pick all the leaves"],0],["Where did the snail climb?",["Onto a leaf","Onto the moon","Into a cup"],0]]},{"id":"d64_en_1_09","grade":1,"t":"The Window Garden","art":"flower","text":"Tess planted beans in two pots. She set one by the window and one behind a box. Each got the same small drink of water.\n\nThe bean by the window grew toward the light. The other looked pale.\n\nTess moved the box away. Now both pots had a bright place. She drew their new leaves in her garden book.","q":[["What was different about the two places?",["The light","The kind of water","The size of the beans"],0],["Why did Tess move the box?",["To let in more light","To stop all the water","To hide a leaf"],0]]},{"id":"d64_en_1_10","grade":1,"t":"The Missing Blue","art":"palette","text":"Sam wanted to paint the sea, but his blue paint was gone. He nearly shut the paint box.\n\nThen he saw the gray sky outside. He mixed white with a little black. He made a soft gray sea with one green wave.\n\n\"The sea has many moods,\" Dad said.\n\nSam put his picture by the window. Today, the gray sea matched the sky.","q":[["Why did Sam use gray?",["His blue paint was gone","He forgot what water was","The brush was blue"],0],["What did Sam discover?",["A sea picture need not be blue","Only one color is allowed","Paint cannot mix"],0]]},{"id":"d64_en_1_11","grade":1,"t":"The Folded Note","art":"paper","text":"Luz drew a sun on a note for her brother. She folded it so it could stand on his desk.\n\nA breeze knocked it flat. Luz folded a small base along the bottom. Now the note stayed up.\n\nWhen her brother came home, the paper sun was waiting. He put his pencil down and drew a little moon beside it.","q":[["What helped the note stand?",["A folded base","A wet brush","A long string"],0],["What did her brother add?",["A moon","A boat","A boot"],0]]},{"id":"d64_en_1_12","grade":1,"t":"The Last Bus Seat","art":"bus","text":"Owen found a seat beside Mom on the bus. He put his backpack on the empty seat across from them.\n\nAt the next stop, a woman got on with a cane. Owen lifted his bag onto his lap.\n\nThe woman sat down and smiled. Owen watched the trees slide past the window. His lap was full, but there was room for everyone.","q":[["Why did Owen move his bag?",["Someone needed a seat","The bag could drive","He wanted to stand on it"],0],["Where did the bag go?",["Onto his lap","Under the bus","Into a tree"],0]]},{"id":"d64_en_2_01","grade":2,"t":"The Cupboard Map","art":"paper","text":"Anya could never find the measuring cups in the community kitchen. Each helper put them in a different cupboard. She wanted a map, but her little brother could not read the labels yet.\n\nThey drew a cup on the right cupboard door and a spoon on the drawer. Anya used dark lines so everyone could see the pictures.\n\nAt the next cooking day, her brother found the cups all by himself. The map did not show a road or a river. It showed where people could help.","q":[["Why did they use pictures?",["Not everyone could read the labels","The cupboards were outside","The cups were invisible"],0],["What did her brother find?",["The measuring cups","A river","A missing dog"],0]]},{"id":"d64_en_2_02","grade":2,"t":"A Room for Rain","art":"rain","text":"Water rushed from the roof into a barrel. When the barrel filled, water spilled beside the steps. Malik noticed that the path became slippery.\n\nWith a grown-up's help, he moved the overflow hose toward a patch of thirsty shrubs. They watched the next rain from the window. The steps stayed clear, and the soil around the shrubs grew dark.\n\nThe barrel still saved water for dry days. Now the extra water had a useful place to go too.","q":[["What was the problem?",["Overflow made the path slippery","The barrel had no water","The shrubs were made of paper"],0],["Where did the hose send extra water?",["To the shrubs","Into the kitchen","Onto the steps"],0]]},{"id":"d64_en_2_03","grade":2,"t":"The Moon Bookmark","art":"moon","text":"Pia cut a moon from stiff paper to mark her place in a book. Her friend asked for one too. Pia had enough silver paper for only one more moon.\n\nShe traced two smaller moons instead. One was thin and curved. The other was nearly round. She gave her friend the choice.\n\nThey opened their books to different pages, with different moons peeking out. Pia had not made matching gifts. She had made enough gifts.","q":[["How did Pia make enough bookmarks?",["She made smaller moons","She bought a telescope","She tore up the books"],0],["What choice did her friend get?",["Which moon to take","Which book to hide","When the sun should set"],0]]},{"id":"d64_en_2_04","grade":2,"t":"A Sound on the Shelf","art":"bell","text":"Each evening, the shelf near Vera's bed made a soft ticking sound. She wondered if a small animal lived behind it.\n\nDad listened with her. The sound began just after they turned off the warm desk lamp. Dad explained that some materials move a tiny bit as they cool.\n\nVera tested this the next evening. The tick came after the lamp went off again. She wrote, \"Not a mouse. A cooling shelf.\" Knowing what made the sound helped her rest.","q":[["When did the ticking begin?",["After the warm lamp went off","Before breakfast","Only when it snowed"],0],["What did Vera do to check the idea?",["Listened again the next evening","Caught a mouse","Threw away the shelf"],0]]},{"id":"d64_en_2_05","grade":2,"t":"The Borrowed Bench","art":"wood","text":"A bench stood beside the garden gate. When it broke, everyone walked past without stopping. Rosa missed the little talks people had there.\n\nShe asked the gardener if they could repair it. Two neighbors brought tools. Rosa sanded a rough edge while an adult held the board steady. They tested the bench together before anyone sat down.\n\nBy evening, the bench was back. A new child sat there with a picture book. Rosa brought her own book and joined him. The repair had made more than a seat.","q":[["Why did Rosa want the bench repaired?",["People used it to spend time together","She wanted a taller gate","The flowers needed a bed"],0],["Who helped with tools?",["Two neighbors","A flock of birds","Nobody"],0]]},{"id":"d64_en_2_06","grade":2,"t":"The Warm Pebble","art":"sun","text":"At the beach, Luis found a pebble warm from the afternoon sun. A pebble under his towel felt cooler. Both looked nearly the same.\n\nHe moved the warm pebble into the shade. He waited while his mother packed their things. When he picked it up again, it was cooler too.\n\nLuis left both pebbles on the beach. He carried home a question instead: would a dark pebble warm faster than a pale one? Tomorrow, he could make a careful test with stones from the yard.","q":[["Why was one pebble warmer?",["It had been in the sun","It had tiny batteries","It was alive"],0],["What did Luis take home?",["A question to test","All the beach stones","The towel's shadow"],0]]},{"id":"d64_en_2_07","grade":2,"t":"The Paper Bridge","art":"bridge","text":"Jin laid a flat sheet of paper between two books. It sagged when he put a toy car on it. His sister folded another sheet into narrow ridges, like a fan.\n\nThey tried the same car with the books the same distance apart. The folded paper held it. Jin drew both bridges and wrote what they had kept the same.\n\n\"We changed the shape, not the paper,\" he said. They parked the car on the folded bridge and left their small discovery on the table for Dad.","q":[["What change made the bridge stronger?",["Folding the paper","Moving the books far apart","Using a smaller car"],0],["Why use the same car both times?",["To compare the two shapes fairly","To give it a name","To change its color"],0]]},{"id":"d64_en_2_08","grade":2,"t":"The Sock Basket","art":"basket","text":"Every wash day, one basket held socks without partners. Mara used to call them lost. Grandpa called them waiting.\n\nThey spread the socks on a blanket and sorted them by size, then color. Some found partners at once. Two were still alone.\n\nMara made those two into soft puppets with paper eyes and no small buttons. That evening, the puppets welcomed everyone to a story. Not every waiting sock found its match, but every sock found a place.","q":[["How did they sort the socks first?",["By size","By smell","By the day of the week"],0],["What happened to the last two socks?",["They became puppets","They became shoes","They vanished"],0]]},{"id":"d64_en_2_09","grade":2,"t":"A Fair Slice","art":"bread","text":"There were three friends and one small round loaf. Bo cut two large slices, then saw that the last piece was much smaller.\n\n\"I can fix that,\" he said. He cut each large slice into three pieces. They put all the pieces on a plate and took turns choosing, one at a time.\n\nNobody's pile looked exactly the same. But each person had enough, and nobody chose twice in a row. They ate slowly and planned what to bake together next time.","q":[["What did Bo notice?",["The last piece was much smaller","There were four loaves","Nobody liked bread"],0],["How did the friends share?",["They took turns choosing pieces","Bo kept everything","They hid the plate"],0]]},{"id":"d64_en_2_10","grade":2,"t":"The Leaf Library","art":"leaf","text":"Nell wanted to know which tree made each leaf on her street. She collected fallen leaves, not leaves still growing on branches. Her uncle helped her use a tree guide.\n\nThey pressed the leaves between scrap paper under a heavy book. Later, Nell made cards with a leaf shape, a tree name, and the place she had found it.\n\nShe called the box her leaf library. When winter hid the leaves, the cards helped her remember the trees. In spring, she planned to look at their buds.","q":[["Which leaves did Nell collect?",["Leaves already on the ground","Every leaf on one tree","Only plastic leaves"],0],["What helped her name the trees?",["A tree guide","A recipe","A bus ticket"],0]]},{"id":"d64_en_2_11","grade":2,"t":"The Evening Mailbox","art":"paper","text":"The neighbors built a little box for kind notes. On Monday, Suri found a note that said, \"Your flowers make my walk cheerful.\" It had no name.\n\nSuri wanted to answer, but she did not know who to thank. She wrote, \"I am glad. Please enjoy the yellow ones opening this week.\" She left it in the box for anyone to read.\n\nBy Friday, someone had drawn the yellow flowers beneath her words. The box was becoming a conversation without anyone needing to ring a doorbell.","q":[["Why could Suri not thank one person?",["The note had no name","She could not write","The box was locked"],0],["What happened to her reply?",["Someone added a flower drawing","It became a real flower","Nobody could see it"],0]]},{"id":"d64_en_2_12","grade":2,"t":"The Two Shadows","art":"tree","text":"At breakfast, Asha drew the shadow of a small tree with chalk. At lunch, the shadow no longer fit her outline. She drew a second outline in another color.\n\nThe tree had not walked. The sun's position in the sky had changed, so the shadow pointed a different way.\n\nAsha asked to go outside once more before supper. Her third drawing was long and thin. The pavement now held three quiet pictures of the same tree at three different times.","q":[["What changed during the day?",["The direction and length of the shadow","The tree's address","The color of the sun"],0],["Why use different chalk colors?",["To tell the outlines apart","To feed the tree","To make rain"],0]]},{"id":"d64_en_2_13","grade":2,"t":"The Repair Ribbon","art":"bow","text":"A small tear ran along the edge of Talia's favorite bag. She thought she would have to stop using it. Her grandfather found a strip of sturdy ribbon.\n\nHe stitched the tear closed and showed her how the ribbon could cover and strengthen the edge. Talia chose blue thread that could be seen, not hidden.\n\nAt the library, a friend admired the bright seam. Talia told her the bag's story. The repair was not a secret. It was a new part of something she loved.","q":[["What did the ribbon do?",["Strengthened the repaired edge","Made the bag disappear","Turned into a handlebar"],0],["Why did Talia choose visible thread?",["She liked showing the repair","She wanted to hide the bag","She had no bag"],0]]},{"id":"d64_en_3_01","grade":3,"t":"The Pause in the Music","art":"piano","text":"During rehearsal, Kit always rushed through the silent spaces in the piano piece. Notes seemed like the important part. Why practice a moment when nothing happened?\n\nHis teacher asked him to listen while she played the tune two ways. First, she hurried without stopping. Then she let each pause last its full time. Kit noticed that the second version felt like someone taking a comfortable breath.\n\nAt home, he marked the pauses with tiny pencil clouds. His sister sat beside him and followed the clouds on the page. When the final note faded, neither spoke at once. This time, Kit let the quiet finish the music.","q":[["What did Kit learn about pauses?",["They help shape the music","They are mistakes","They should always be skipped"],0],["Why did he draw clouds?",["To remind himself to wait","To cover the notes","To predict rain"],0]]},{"id":"d64_en_3_02","grade":3,"t":"The Shade Survey","art":"tree","text":"The playground benches felt hot after lunch. Noor suggested planting a tree, but the class needed to choose a place. They could not judge by looking at the yard just once.\n\nFor several days, small groups marked where shadows fell in the morning and afternoon. They drew the marks on a shared map. A bench shaded at breakfast sat in full sun by lunch.\n\nTheir map helped the school gardener explain which young trees might grow well there. Planting would take planning, water, and time. Noor liked that their careful looking had become useful. While they waited for a tree, the class moved one bench beneath an existing shelter.","q":[["Why did they check shadows at different times?",["Shade moved during the day","The benches changed color","The map needed more trees drawn on it"],0],["What helped right away?",["Moving a bench beneath a shelter","Waiting for a seed to grow overnight","Painting the sun"],0]]},{"id":"d64_en_3_03","grade":3,"t":"The Long Stitch","art":"bow","text":"Iris wanted to mend a torn blanket for the reading corner. Her first stitches were uneven. Some were tiny; others stretched like bridges. She pulled the thread out twice.\n\nHer aunt put a small scrap beside her. \"Practice here first. The blanket can wait.\"\n\nIris tried ten slow stitches. Then ten more. She noticed that relaxing her shoulders helped her hands stay steady. When she returned to the blanket, her stitches were still not identical, but they held the fabric together.\n\nThe children in the reading corner did not count the stitches. They tucked the repaired blanket around their knees. Iris sat with them, warm beneath her own patient work.","q":[["Why did Iris use a scrap first?",["To practice without redoing the blanket","To make a second blanket instantly","To hide the tear"],0],["What mattered most about the finished stitches?",["They held the fabric together","They were invisible","They were all different colors"],0]]},{"id":"d64_en_3_04","grade":3,"t":"The Rain Measure","art":"rain","text":"A storm sounded enormous on the metal porch roof. Diego guessed that it must have dropped more rain than any other storm that month. His sister was not sure.\n\nThey checked the straight-sided rain gauge they had placed in the open garden. The water level was lower than after last week's quiet, steady rain. The loud storm had passed quickly.\n\nDiego added both measurements to their weather chart. He wrote a note about the roof making drops sound louder. His guess had been sensible, but the measurement told a different story. He did not erase his guess. Keeping it helped him remember what he had learned.","q":[["Why was Diego's guess not enough?",["Loudness did not show the total rainfall","Rain cannot be measured","The chart was blank forever"],0],["What did he keep beside the measurement?",["His earlier guess","A bucket of thunder","The porch roof"],0]]},{"id":"d64_en_3_05","grade":3,"t":"The Shared Window","art":"home","text":"The apartment hall had one small window and a wide, empty sill. Amelie asked the neighbors whether they would like plants there. One neighbor liked flowers. Another worried about water dripping onto the floor.\n\nInstead of choosing for everyone, Amelie brought a sketch to their next meeting. It showed two pots in deep trays and a small watering schedule. A neighbor offered plants that could grow in the window's gentle light.\n\nThey tried the plan for a month. The trays caught the drips. People stopped to notice new leaves. The window still belonged to everyone, but now taking care of it gave them something to share.","q":[["How did Amelie respond to the worry about water?",["She planned deep trays","She ignored the neighbor","She removed the window"],0],["Why have a watering schedule?",["To share the care","To make plants grow in darkness","To count apartments"],0]]},{"id":"d64_en_3_06","grade":3,"t":"The Postcard Drawer","art":"paper","text":"Grandfather kept postcards in a drawer, mixed with old envelopes. Sami wanted to sort them by country. Grandfather suggested sorting them by the people who had sent them instead.\n\nThey tried both ways. The country piles made a picture of faraway places. The people piles told longer stories: a friend moving house, a cousin learning to write, a sister sending the same cheerful greeting every summer.\n\nSami put the cards in sleeves and made two lists. Nothing in the drawer had changed, but the different arrangements helped them notice different things. Grandfather chose one postcard to keep by his lamp. It showed an ordinary street and carried an extraordinary memory.","q":[["What did sorting by sender reveal?",["Stories about the people over time","The weight of the drawer","Only the price of stamps"],0],["Why did Sami make two lists?",["Both arrangements were useful","One list had no letters","Grandfather disliked postcards"],0]]},{"id":"d64_en_3_07","grade":3,"t":"The Night Garden Sign","art":"flower","text":"The community garden closed at dusk. Visitors sometimes turned on bright phone lights to look at the flowers. Lila wondered whether the garden needed more lamps.\n\nThe gardener showed her pale flowers that opened in the evening. Moths visited them, carrying pollen between blossoms. Too much light could disturb some nighttime visitors.\n\nLila designed a sign inviting people to enjoy the garden quietly from the path before closing. Her drawing showed a moth above a pale bloom. The sign did not ask anyone to catch or feed an animal. It asked people to notice what was already happening. That evening, Lila watched one moth arrive, without switching on a light.","q":[["Why did Lila change her idea about more lamps?",["Light could disturb nighttime visitors","Flowers only grow indoors","Moths need phone screens"],0],["What did the sign encourage?",["Quiet observation from the path","Catching every moth","Leaving the gate open all night"],0]]},{"id":"d64_en_3_08","grade":3,"t":"The Tin's New Job","art":"cup","text":"A biscuit tin had lost its lid. Theo's family could no longer use it to keep biscuits crisp. He wondered whether it belonged in the recycling.\n\nAt the workshop, loose pencils rolled off the table. Theo lined the tin with a piece of felt and set the pencils upright inside. The heavy bottom made it hard to knock over.\n\nHe painted a small pencil on the outside so younger visitors would know its job. The tin did not need to become new again. Its scratches remained, and so did the faint picture of biscuits on one side. It simply needed a purpose that did not require a lid.","q":[["Why was the tin poor for storing biscuits?",["It had no lid","It was too quiet","It had no handle"],0],["Why did it work as a pencil holder?",["Its heavy bottom helped it stay upright","The pencils became biscuits","The felt made a new lid"],0]]},{"id":"d64_en_3_09","grade":3,"t":"A Map of Sounds","art":"ear","text":"On a quiet walk with her mother, Jada drew a map without street names. She marked the fountain with curved lines, the gate with a little squeak, and a tree with dots for birdsong.\n\nAt first, she thought the quietest place would have no marks. But beneath a sheltered bench she heard leaves brushing together and the faint hum of a bus far away.\n\nBack home, her brother followed the map while Jada described the walk. He imagined a place that the usual street map had not shown him. Quiet did not mean empty. Sometimes it meant that smaller sounds finally had room to be heard.","q":[["What did Jada put on her map?",["Sounds she noticed","Only street numbers","The names of every bird"],0],["What changed in the quiet place?",["Small sounds became noticeable","All sound disappeared","The fountain stopped forever"],0]]},{"id":"d64_en_3_10","grade":3,"t":"The Small Exhibit","art":"picture","text":"Oscar's class planned a display about ordinary objects with unusual histories. He brought a wooden spoon. At first, he worried that it would seem dull beside the other exhibits.\n\nHis father explained that three generations had used the spoon to stir the same winter soup. A dark patch on its handle came from years of being held. A shallow dent came from a fall long ago.\n\nOscar wrote labels for the marks instead of polishing them away. At the exhibit, visitors leaned closer to read. The spoon had not traveled to a palace or crossed an ocean. Its story was about familiar hands, shared meals, and the usefulness of being kept.","q":[["Why did Oscar leave the marks visible?",["They helped tell the spoon's history","He wanted to hide the spoon","The labels would not stick elsewhere"],0],["What made the spoon special?",["Its family history and use","It was made of gold","It could stir by itself"],0]]},{"id":"d64_en_3_11","grade":3,"t":"The Windbreak Test","art":"wood","text":"The class wanted to keep their model garden from being battered by a fan. Jun built a solid wall from cardboard. Bea built a fence with small gaps.\n\nThey used the same fan setting and placed each barrier the same distance from the paper plants. The solid wall blocked the air directly behind it, but paper leaves near its sides shook hard. The fence let a softer flow through its gaps.\n\nThey repeated the test before choosing a design. Neither model could tell them everything about a real garden. Still, their small experiment showed why it can help to compare ideas instead of choosing only the one that looks strongest.","q":[["What did they keep the same?",["The fan setting and distance","The shape of both barriers","The color of every leaf"],0],["Why repeat the test?",["To check whether the result happened again","To wear out the fan","To make the cardboard heavier"],0]]},{"id":"d64_en_3_12","grade":3,"t":"The Last Page Space","art":"book","text":"Maya filled a notebook with drawings from the garden. Only one page remained. She saved it for something wonderful, so each visit she closed the book without drawing.\n\nOne evening, she noticed a bent stem holding a single drop of water. It was not a grand view. She drew the curve of the stem and the tiny upside-down world inside the drop.\n\nAt home, Maya realized that waiting for the perfect subject had kept her from looking closely. She wrote the date beneath her drawing. When the notebook was full, she did not feel that the garden was finished. She felt ready to begin looking again in a new book.","q":[["Why had Maya left the page blank?",["She was waiting for a perfect subject","She had no pencil","The garden had vanished"],0],["What did she finally draw?",["A bent stem with a water drop","A palace","An empty notebook"],0]]},{"id":"d64_en_4_01","grade":4,"t":"The Quiet Repair Table","art":"wood","text":"The library's repair afternoon was usually crowded with talk. One visitor, Ms. Chen, stepped back whenever several people spoke at once. Eva first thought she did not want to join in.\n\nThen Eva noticed how closely Ms. Chen watched the demonstrations. She asked whether a quieter table would help. The librarian found a corner away from the door, and the volunteers agreed to demonstrate one step at a time.\n\nMs. Chen brought over a broken picture frame. Soon she was showing Eva how to hold the corners square while the glue dried. A quieter space had not removed the visitor from the group. It had made room for her to contribute.\n\nAt closing time, Eva added a small sign to the table: A calm place to work. She did not need to explain anyone's private reasons for using it.","q":[["Why was Eva's first guess incomplete?",["Ms. Chen wanted to join but found the noise difficult","Ms. Chen disliked frames","The library was closed"],0],["What did the quieter table make possible?",["Participation and sharing a skill","Keeping every visitor apart","Doing all repairs without help"],0]]},{"id":"d64_en_4_02","grade":4,"t":"The Seed Envelope","art":"flower","text":"Among the garden club's seed envelopes, Noah found one labeled only \"Grandma's yellow beans.\" He wanted to replace the untidy handwriting with a proper printed name.\n\nHis grandmother asked him to keep the old label inside the new envelope. The beans had come from a neighbor, who had shared them during a difficult year. The handwriting belonged to that neighbor.\n\nNoah still needed useful planting information, so he added a second card with the sowing date, spacing, and a description of the pods. One card would help the beans grow. The other preserved why the family had kept them.\n\nThat autumn, he saved seeds from healthy plants and shared a packet with a friend. He included both practical instructions and the story of the name. Accurate records and personal memories could live in the same small envelope.","q":[["Why keep the handwritten label?",["It preserved a connection to the neighbor","It made the seeds heavier","Printed words cannot name beans"],0],["What was the purpose of the second card?",["To record planting information","To replace the family memory","To show that seeds need no care"],0]]},{"id":"d64_en_4_03","grade":4,"t":"An Unfinished Pattern","art":"pattern","text":"At the community center, Lena helped arrange a mosaic made from donated tiles. The plan called for a blue border, but there were not enough blue pieces to reach the final corner.\n\nShe could have bought more, though their color might not have matched. Instead, the group spread all the leftover pieces on a cloth. A child noticed that the green and blue fragments together looked like a riverbank.\n\nThey revised the border so the change began gradually, not suddenly at the last corner. Lena kept a sketch of the original plan beside the finished mosaic. It showed how a shortage had invited everyone to look again.\n\nThe new pattern was not simply a mistake covered up. It was a decision made together, using what they had and explaining why the design had changed.","q":[["What caused the group to revise the border?",["They lacked enough blue tiles","The center had no walls","Nobody liked patterns"],0],["Why keep the original sketch?",["To show how their thinking changed","To pretend the change never happened","To use it as a tile"],0]]},{"id":"d64_en_4_04","grade":4,"t":"The Window Reflection","art":"moon","text":"A bird touched the classroom window and flew back to a nearby branch. The children were relieved that it seemed able to fly, but they wanted to understand what had happened.\n\nFrom outside, the glass reflected the garden so clearly that it looked like open space. Their teacher explained that a bird might not recognize the barrier. They researched window markings designed to make glass easier for birds to notice.\n\nWith school permission, an adult helped place a close-spaced pattern on the outside of the pane. The class watched from a distance over the following weeks. They recorded what they saw rather than claiming the problem was solved after one afternoon.\n\nThe window still brought light into the room. Now it also reminded the class that a view can look very different depending on where you stand.","q":[["Why might the bird have approached the glass?",["It reflected the garden like open space","It wanted to read a book","The glass was a tree"],0],["Why observe for several weeks?",["One quiet afternoon was not enough evidence","Birds only fly once a month","The pattern needed a name"],0]]},{"id":"d64_en_4_05","grade":4,"t":"The Long Table Recipe","art":"bread","text":"At a neighborhood supper, everyone asked for Mr. Rivera's soup recipe. He could list the ingredients, but the amounts were harder. He had cooked it by eye for years.\n\nMina offered to help record the next batch. They measured each addition and noted when he adjusted the seasoning. The first written recipe was detailed, but one instruction still read, \"Cook until it feels ready.\"\n\nMina asked what signs he looked for. He described tender beans, soft carrots, and a broth that smelled less sharp. She wrote those clues beside an approximate cooking time.\n\nThe finished page did not turn cooking into a rigid rule. It gave a beginner a place to start and ways to notice when a change was needed. At the next supper, Mr. Rivera handed the recipe to someone else and enjoyed sitting down before everyone arrived.","q":[["Why was the recipe difficult to record?",["Mr. Rivera usually judged amounts by eye","He had never made soup","The ingredients had no names"],0],["Why add sensory clues to the cooking time?",["Different batches may be ready at different times","Clocks cannot be used in kitchens","Every soup must smell sharp"],0]]},{"id":"d64_en_4_06","grade":4,"t":"The Shadow Exhibition","art":"sun","text":"For the spring exhibition, Arlo photographed one tree at the same hour every Saturday. He expected twelve nearly identical pictures. Instead, the changing light made each image distinct.\n\nSome differences came from clouds. Others came from the sun being higher in the sky as spring advanced. Leaves gradually filled the branches, making the shadow on the ground more crowded.\n\nArlo arranged the photographs in date order and added short notes about the weather. Without those notes, visitors might have mistaken a cloudy day for a seasonal change. His labels did not explain everything, but they helped separate what he had observed from what he was guessing.\n\nThe exhibition took only a little space on the wall. It held three months of patient attention. Afterward, Arlo put the camera away and spent a morning enjoying the tree without trying to collect it.","q":[["Why include weather notes?",["Clouds could explain some differences","The tree changed its name","All pictures were taken at night"],0],["What did the project require most?",["Repeated careful observation","A faster-growing tree","A different camera every week"],0]]},{"id":"d64_en_4_07","grade":4,"t":"The Borrowing Basket","art":"basket","text":"A basket of spare mittens appeared by the school entrance. Children could borrow a pair and return it later. Within a week, the basket was almost empty, and some students said the idea had failed.\n\nRhea suggested asking what had happened before deciding. A few mittens had gone home by accident. Several children had no warm pair of their own. Some simply did not know where to return them.\n\nThe class added a clear return spot and invited families to donate clean, usable pairs. They also agreed that a child who needed mittens could keep a pair without explaining their situation in public.\n\nBy the end of winter, the basket looked different each day. Its purpose was not to remain full. Its purpose was to help hands stay warm. Understanding that changed how the class measured success.","q":[["Why did Rhea ask questions first?",["An empty basket could have several explanations","She wanted to stop sharing","She disliked mittens"],0],["How did the class redefine success?",["Whether the basket helped people stay warm","Whether every mitten stayed in school","Whether nobody borrowed anything"],0]]},{"id":"d64_en_4_08","grade":4,"t":"The Faded Garden Plan","art":"paper","text":"Behind a cabinet, the caretaker found a plan for the school garden drawn thirty years earlier. A pond filled the middle of the drawing. Outside, there was only a shallow grassy dip.\n\nSofia wanted to know whether the pond had ever been built. The old plan alone could not tell her. She looked at photographs in the school archive and spoke with a former teacher. A photograph showed the pond, and the teacher remembered when it had been filled in.\n\nSofia made a display with the plan, the photograph, and a note describing the conversation. She marked which details came from each source.\n\nThe grassy dip became more interesting once she knew its history. But she also learned something about evidence: a drawing may show an intention, while a photograph can show what was actually there at a particular moment.","q":[["Why was the old plan not enough?",["A plan might show something never built","All plans are false","Grass cannot cover old features"],0],["What did Sofia do in her display?",["Identified the source of each detail","Invented a date for the pond","Removed the photograph"],0]]},{"id":"d64_en_4_09","grade":4,"t":"A Little More Silence","art":"ear","text":"The museum invited students to write labels for a listening room. Ellis drafted a long explanation of every sound visitors might hear: a stream, leaves, distant wheels, footsteps on gravel.\n\nDuring a trial visit, his cousin spent most of the recording reading the label. She missed the stream entirely. Ellis realized his careful explanation was competing with the experience.\n\nHe shortened the label to a few inviting questions: Which sound feels nearest? Which one did you notice last? A longer explanation remained available on a separate card for visitors who wanted it.\n\nThe new label did not make the room less educational. It allowed people to listen first and decide what they wanted to learn next. Ellis kept his original draft in a folder. Cutting words had taken as much thought as writing them.","q":[["What was the problem with the first label?",["Reading it distracted visitors from listening","It used no words","The stream recording was silent"],0],["Why keep a separate information card?",["Some visitors would still want more detail","To hide every explanation","To replace the recording"],0]]},{"id":"d64_en_5_01","grade":5,"t":"The Library's Empty Space","art":"book","text":"When the library replaced a tall shelf, it left an empty patch near the window. The planning group quickly filled a page with ideas: a display, a game table, a cabinet for puzzles. Nadiya suggested leaving the space empty for a month.\n\nAt first, this sounded like no plan at all. She proposed something more specific: watch how people used the space before choosing furniture. Volunteers recorded patterns without collecting names or photographing visitors.\n\nA person using a walker could now turn comfortably. Two children spread a large map on the floor. On rainy afternoons, someone stood there to shake water from a coat before sitting down.\n\nThe observations did not settle every question. They did show that empty space was doing useful work. The group chose a small movable table rather than another heavy cabinet. Their final plan included room for purposes they had not yet imagined.","q":[["Why did Nadiya suggest waiting?",["To observe how the space was used","To avoid ever making a decision","To count visitors' private information"],0],["What conclusion did the observations support?",["Flexible open space had value","Every empty space needed a cabinet","Furniture could not be moved"],0]]},{"id":"d64_en_5_02","grade":5,"t":"The Label on the Blanket","art":"bow","text":"Tucked into a handmade blanket was a label with three names. Celia assumed they were the people who had owned it. Her aunt recognized only one: the person who had spun the wool.\n\nThey contacted a local craft group, and an older member explained the other names. One belonged to the dyer; another to the weaver. The blanket carried a record of making, not just owning.\n\nCelia had planned to replace the worn label with a neat new one. Instead, she photographed it for the family album and stitched a protective pocket around it, leaving the writing visible. She added a separate note recording what they had learned and what remained uncertain.\n\nAt bedtime, the blanket felt much as it always had. Yet Celia now understood its warmth as the result of several people's skill. The label had made work that was easy to overlook visible again.","q":[["What did the three names record?",["People involved in making the blanket","Three former pets","The prices of three blankets"],0],["Why record uncertainties too?",["To avoid presenting guesses as established facts","To make the history sound mysterious","To erase the old label"],0]]},{"id":"d64_en_5_03","grade":5,"t":"The Pond's Changing Edges","art":"leaf","text":"A community group wanted to improve the path around a small pond. Their first drawing put the new path close to the water everywhere. It looked tidy and used little gravel.\n\nDuring a walk with a naturalist, Omar noticed that the pond's edge was not a fixed line. After rain, water reached the grasses beyond it. In dry weather, soft mud appeared where the drawing showed a firm bank. The naturalist also pointed out places where frogs sheltered among plants.\n\nOmar helped add seasonal observations to the plan. The revised path curved farther from the water in several places. A short boardwalk crossed one damp patch without filling it with stones.\n\nThe new route was slightly longer. It was also based on a fuller understanding of the place. A neat line on paper had become a path that made room for change.","q":[["What assumption did the first plan make?",["The pond's edge stayed in one position","The pond had no water","Gravel would grow into grass"],0],["Why was the longer route useful?",["It respected wet ground and habitats","It made everyone walk through the pond","It removed every plant"],0]]},{"id":"d64_en_5_04","grade":5,"t":"The Sound Archive","art":"ear","text":"A local history group asked residents to contribute recordings of everyday sounds. Amara first thought of spectacular ones: a parade, a bell tower, thunder. Her grandfather suggested the soft click of his old sewing machine.\n\nShe asked his permission before recording. He chose what to share and listened to the result. Beside the file, Amara added the date, the machine's name, and his explanation of why he still used it. She left out a conversation that had been caught accidentally in the background.\n\nAt the archive's open day, visitors recognized sounds that no longer filled their own homes. The sewing machine prompted stories about repaired coats and curtains made from saved cloth.\n\nAmara realized that preserving a sound also required preserving context and respecting the people around it. A recording could hold a moment, but it should not take someone's privacy along with it.","q":[["Why did Amara remove the background conversation?",["It was not intended to be shared","It was the loudest sound in history","The machine could not be heard at all"],0],["What helped listeners understand the recording?",["Permission, a date, and useful context","Only a file number","A made-up description"],0]]},{"id":"d64_en_5_05","grade":5,"t":"The Fair Comparison","art":"science","text":"For the school garden, two companies offered compost bins. One advertisement claimed its bin made compost \"twice as fast.\" The student council liked the sound of that, but Meera wanted to know what had been compared.\n\nThe advertisement gave no details about temperature, ingredients, or how often the material was mixed. A gardener explained that these conditions could affect the result as much as the container did.\n\nThe council did not accuse the company of lying. Instead, they requested more information and listed what mattered at their school: safe access, durability, cost, and a size the volunteers could manage. They also visited a garden using each design.\n\nTheir final choice was not based on the most exciting sentence. It was based on evidence relevant to their own needs. Meera wrote the reasoning down so next year's council would understand the decision, not merely inherit it.","q":[["Why was the speed claim hard to judge?",["The comparison conditions were missing","Compost never changes","Both bins were invisible"],0],["What did the council consider?",["Evidence and their school's practical needs","Only the largest printed words","Only the color of the advertisement"],0]]},{"id":"d64_en_5_06","grade":5,"t":"The Lantern Route","art":"lamp","text":"The town's evening walk followed a route decorated with paper lanterns containing small battery lights. Before the event, Jonah's group tested the path at the time families would actually use it.\n\nTheir map looked straightforward in daylight. At dusk, a narrow step was difficult to distinguish from the paving beside it. One turning sign faced people approaching from the wrong direction. The quietest viewing place had no space for a wheelchair to turn.\n\nThe group reported these details and worked with the organizers on changes. They marked the step clearly, turned the sign, and moved a display to leave a wider resting area. They did not add brightness everywhere; they directed light where it helped.\n\nOn the evening of the walk, Jonah noticed people enjoying the lanterns rather than struggling to find their way. The most useful parts of the planning were the problems visitors never had to encounter.","q":[["Why test the route at dusk?",["Conditions differed from daylight","The map could only open at night","Battery lights need moonlight"],0],["What was the goal of the changes?",["A clearer, more accessible route","The brightest possible street","Keeping visitors from resting"],0]]},{"id":"d64_en_5_07","grade":5,"t":"The Unsent Letter","art":"paper","text":"During a family-history project, Hana found a letter her great-aunt had written but never mailed. It described a disagreement with a friend. The sentences were sharp, and the ending was unfinished.\n\nHana wanted to include it in her class presentation because it seemed more dramatic than the other papers. Her mother asked whether a private draft should be treated like a public statement. They did not know why the letter had remained unsent or how the friendship had continued.\n\nHana changed her presentation. She described what different kinds of documents could and could not tell us, without showing the personal letter or naming the friend. A shopping list, a postcard, and a diary each offered a different view of the same period.\n\nThe letter still mattered to Hana. Keeping it private did not make her research less honest. It helped her recognize the limits of what the surviving evidence could justify sharing.","q":[["Why was the unsent letter difficult evidence?",["Its purpose and later context were uncertain","It had too few stamps","All handwritten documents are public"],0],["What did Hana decide?",["Explain source limits without exposing private details","Invent the missing ending","Mail the old letter to her class"],0]]},{"id":"d64_en_5_08","grade":5,"t":"The Repair That Stayed Visible","art":"wood","text":"A crack crossed the top of the community center's wooden table. Some members wanted a replacement. Others valued the table because generations of neighbors had gathered around it. A carpenter examined it before anyone made a decision.\n\nThe damage was repairable. With a strong joint and a small inset of contrasting wood, the table could be safe and useful again. The inset would remain visible. It would not pretend that the crack had never happened.\n\nElias helped document the work for the center's noticeboard. He included the carpenter's assessment, the materials used, and the reason the group had chosen repair. Keeping an old object was not automatically the best choice; in this case, they had checked that it was practical.\n\nAt the next gathering, people ran their fingers along the smooth inset. The table carried an additional story without losing its old purpose: making a place for people to meet.","q":[["Why consult a carpenter first?",["To assess whether repair was safe and practical","To choose a secret name","To make the crack larger"],0],["What did the contrasting inset show?",["The history of the repair","That the table had never cracked","Where people must not sit"],0]]},{"id":"d64_en_5_09","grade":5,"t":"The Morning After the Experiment","art":"science","text":"Inez's class compared two ways of keeping a tray of seedlings moist. Their first set of measurements appeared to favor a cloth cover. Before announcing a result, they inspected their notes.\n\nOne tray had stood nearer the radiator. On two days, different students had used different measuring cups. These were not small details they could simply leave out; either might have influenced how quickly the trays dried.\n\nThe class wrote a careful preliminary statement: their test raised a useful question but did not yet provide a fair comparison. They planned a second trial with matched positions and a shared measuring method.\n\nInez had hoped for a clear answer to put on the wall. Instead, she displayed both the first attempt and the revised plan. The project showed something valuable about investigation: noticing a weakness is not the same as failing to learn. Sometimes it is the step that makes the next result worth trusting.","q":[["Why was the first comparison uncertain?",["Tray positions and measuring methods differed","The class wrote notes","Seedlings never need water"],0],["What did the revised plan aim to do?",["Keep important conditions consistent","Guarantee the cloth would win","Avoid taking measurements"],0]]},{"id":"d64_en_5_10","grade":5,"t":"The Bench Facing West","art":"sunrise","text":"For years, a bench in the courtyard faced a blank wall. When the center asked for improvement ideas, most people suggested painting the wall. Leila proposed turning the bench toward the evening sky instead.\n\nThe idea sounded simple, but the group tested it with movable chairs before shifting the heavy bench. They checked glare, room for people to pass, and whether the new view could be enjoyed from different seated heights. One neighbor preferred the old sheltered spot on windy days.\n\nThe final arrangement kept a smaller seat by the wall and turned the main bench slightly, rather than directly into the setting sun. The change reflected several people's experiences, not just the first attractive sketch.\n\nAt the opening, nothing spectacular happened. People sat down, watched the clouds grow pink, and stayed a little longer than usual. Leila thought that was a good result: a shared place had become more welcoming without needing to become louder or grander.","q":[["Why test with movable chairs?",["To explore effects before moving the heavy bench","To avoid listening to neighbors","To make the sky change color"],0],["What shaped the final arrangement?",["Several people's needs and observations","Only the first sketch","A rule that every seat must face west"],0]]}],"es":[{"ref":"es_k1","grade":0,"q":[["¿A quién quiere quien habla?",["A su mamá","A un barco","A una piedra"],0],["¿Qué hace la mamá?",["Le da cariño","Esconde la casa","Corre por el mar"],0]],"art":"book"},{"ref":"es_k2","grade":0,"q":[["¿Qué animal es Pepe?",["Un pato","Un ratón","Un gato"],0],["¿Dónde cae Pepe?",["En el agua","En una taza","En una nube"],0]],"art":"book"},{"ref":"es_k3","grade":0,"q":[["¿Cómo es la luna del texto?",["Blanca","Verde","Roja"],0],["¿Qué se dice del sol?",["Que es grande","Que es una casa","Que está en una caja"],0]],"art":"book"},{"ref":"es_k4","grade":0,"q":[["¿Qué encontró el ratón?",["Un botón","Una llave","Una flor"],0],["¿Para qué usó el botón en el cuento?",["Para jugar como con un balón","Para cocinar sopa","Para hacer una puerta"],0]],"art":"book"},{"ref":"es_k5","grade":0,"q":[["¿Para quién es la piña?",["Para su amiga","Para un pez","Para nadie"],0],["¿Cómo se describe a la amiga?",["Risueña","Dormida","Enfadada"],0]],"art":"book"},{"ref":"es_k6","grade":0,"q":[["¿Cómo llega Chema?",["Mojado","Con alas","Cubierto de nieve"],0],["¿Qué le da mamá?",["Chocolate caliente","Una piedra","Un paraguas de papel"],0]],"art":"book"},{"ref":"es_k7","grade":0,"q":[["¿Qué cuidados recibe la semilla?",["Agua y sol","Pintura y sal","Solo una caja"],0],["¿Qué aparece al final?",["Una flor","Un zapato","Un pez"],0]],"art":"book"},{"ref":"es_11","grade":1,"q":[["¿Qué salió de la caja?",["un globo azul","un pez","un zapato"],0],["¿Quién ayudó a Dot?",["el oso","el gato","la luna"],0]],"art":"book"},{"ref":"es_12","grade":1,"q":[["¿Dónde salta el sapo?",["En el jardín","En el mar","Dentro de un libro"],0],["¿Qué hace el sapo en la historia?",["Saltar","Tejer","Conducir"],0]],"art":"book"},{"ref":"es_13","grade":1,"q":[["¿Por qué las estrellas parecen pequeñas?",["Están muy lejos","Son todas del tamaño de un botón","Solo existen de día"],0],["¿Qué es también nuestro sol?",["Una estrella","Una luna","Un planeta"],0]],"art":"book"},{"ref":"es_14","grade":1,"q":[["¿Quién prepara las tortillas?",["La abuela","Un pato","Un robot"],0],["¿Cómo se cocina la tortilla en el texto?",["Sobre el comal caliente","Dentro de una caja fría","En el jardín"],0]],"art":"book"},{"ref":"es_21","grade":2,"q":[["¿Quién se comió las galletas?",["un pajarito","el perro","Lucía"],0],["¿Qué pista había en el piso?",["plumas","agua","hojas"],0]],"art":"book"},{"ref":"es_22","grade":2,"q":[["¿Qué formó los arcos con el tiempo?",["El viento y el agua","Un lápiz","Un solo soplido"],0],["¿Fue un cambio rápido?",["No, tardó muchísimo tiempo","Sí, un minuto","Sí, una noche"],0]],"art":"book"},{"ref":"es_23","grade":2,"q":[["¿Qué deseaba Toto?",["Volar","Aprender a cocinar","Vivir bajo el agua"],0],["¿Qué le dio al final sensación de volar?",["Correr con las orejas al aire","Encontrar alas de verdad","Subir a la luna"],0]],"art":"book"},{"ref":"es_24","grade":2,"q":[["¿Qué separan las gotas de agua?",["La luz en colores","Las nubes en piedras","La tierra en hojas"],0],["¿Qué hace falta además de gotas para ver este arcoíris?",["Luz del sol","Un tambor","Una puerta"],0]],"art":"book"},{"id":"d64_es_0_01","grade":0,"t":"La cama de Lolo","art":"pup","text":"Lolo es un perro. Tiene una cama.\n\nEn la cama hay un calcetín.\n\nLolo lo toca con la pata.\n\nLuego se hace una bola.\n\nLolo duerme. El calcetín se queda a su lado.","q":[["¿Qué animal es Lolo?",["Un perro","Un pez","Una rana"],0],["¿Qué hay en su cama?",["Un calcetín","Una taza","Una flor"],0]]},{"id":"d64_es_0_02","grade":0,"t":"Una taza para Ana","art":"cup","text":"La taza de Ana es pequeña.\n\nPapá le pone un poco de leche.\n\nAna toma un sorbo. No se derrama nada.\n\nPapá tiene una taza grande.\n\nCada uno tiene su taza. Las dos están en la mesa.","q":[["¿Qué toma Ana?",["Leche","Sopa","Agua de lluvia"],0],["¿Cómo es su taza?",["Pequeña","Enorme","Tan alta como la mesa"],0]]},{"id":"d64_es_0_03","grade":0,"t":"Luz para leer","art":"lamp","text":"Ya es de noche. Leo abre un libro.\n\nLa lámpara da una luz suave.\n\nEn el libro hay un gato gris.\n\nLeo se lo enseña a su mamá.\n\nMiran juntos. Después cierran el libro y descansan.","q":[["¿Qué ven en el libro?",["Un gato","Un tren","Un árbol"],0],["¿Qué les da luz?",["La lámpara","El libro","Un zapato"],0]]},{"id":"d64_es_0_04","grade":0,"t":"La hoja roja","art":"leaf","text":"Una hoja roja cae al suelo.\n\nLina la recoge. La hoja está seca.\n\nLina la pone entre dos papeles.\n\nEncima deja un libro.\n\nMañana mirará si la hoja sigue tan arrugada.","q":[["¿De qué color es la hoja?",["Roja","Azul","Negra"],0],["¿Qué pone Lina encima de los papeles?",["Un libro","Un vaso de agua","Una pelota"],0]]},{"id":"d64_es_0_05","grade":0,"t":"Sitio para dos","art":"cat","text":"El gato está en la manta.\n\nLlega el perro y quiere sentarse.\n\nEl gato se mueve un poquito.\n\nEl perro se tumba a su lado.\n\nAhora los dos caben. La manta está calentita.","q":[["¿Quién llega junto al gato?",["El perro","El pato","La abeja"],0],["¿Para qué se mueve el gato?",["Para dejar sitio","Para mojarse","Para salir corriendo"],0]]},{"id":"d64_es_0_06","grade":0,"t":"La semilla de Inés","art":"flower","text":"Inés pone tierra en un vaso.\n\nHace un hoyito y deja una semilla.\n\nLe da un poco de agua.\n\nPasan unos días.\n\nUna punta verde sale de la tierra. Inés sonríe.","q":[["¿Qué deja Inés en el hoyito?",["Una semilla","Un botón","Una llave"],0],["¿Qué sale de la tierra?",["Una punta verde","Un zapato","Una campana"],0]]},{"id":"d64_es_0_07","grade":0,"t":"Suena la lluvia","art":"rain","text":"La lluvia toca la ventana.\n\nTin, tin, tin.\n\nYo toco mis rodillas.\n\nMamá hace lo mismo.\n\nLuego dejamos de tocar. Ahora escuchamos solo la lluvia.","q":[["¿Dónde suena la lluvia?",["En la ventana","Dentro del libro","En la nevera"],0],["¿Qué hacemos al final?",["Escuchar","Correr por la calle","Tocar más fuerte"],0]]},{"id":"d64_es_0_08","grade":0,"t":"La campanita","art":"bell","text":"Nora busca su campanita.\n\nMira bajo la mesa. Allí no está.\n\nAbre la bolsa. ¡Aquí está!\n\nLa hace sonar una vez.\n\nLuego la guarda en una caja para encontrarla mañana.","q":[["¿Dónde estaba la campanita?",["En la bolsa","Bajo la mesa","En una rama"],0],["¿Para qué la guarda en una caja?",["Para encontrarla después","Para darle de comer","Para hacerla crecer"],0]]},{"id":"d64_es_0_09","grade":0,"t":"Un barco de hoja","art":"boat","text":"Abuelo pone una hoja en un cuenco con agua.\n\nYo soplo muy suave.\n\nLa hoja navega hasta el borde.\n\nAbuelo dice que parece un barquito.\n\nDejo de soplar. El barco descansa.","q":[["¿De qué es el barquito?",["De una hoja","De una piedra","De una taza"],0],["¿Qué lo mueve?",["Un soplo suave","Una campana","Un lápiz"],0]]},{"id":"d64_es_0_10","grade":0,"t":"El pan del desayuno","art":"bread","text":"Hay pan en la mesa.\n\nEva parte un trozo para ella.\n\nParte otro para su hermano.\n\nQuedan migas. Las juntan en el plato.\n\nLa mesa vuelve a estar limpia.","q":[["¿Con quién comparte Eva el pan?",["Con su hermano","Con un pez","Con nadie"],0],["¿Dónde ponen las migas?",["En el plato","En la cama","En un libro"],0]]},{"id":"d64_es_0_11","grade":0,"t":"Una nube lenta","art":"cloud","text":"Veo una nube desde el patio.\n\nParece una oveja.\n\nMi hermana dice que parece pan.\n\nLa nube cambia de forma.\n\nNo tenemos que elegir. Podemos mirar las dos.","q":[["¿Qué miran las hermanas?",["Una nube","Una taza","Una puerta"],0],["¿Qué hace la nube?",["Cambia de forma","Baja a cenar","Se vuelve una piedra"],0]]},{"id":"d64_es_0_12","grade":0,"t":"La puerta suave","art":"door","text":"Tomás va a cerrar la puerta.\n\nSu hermanita ya duerme.\n\nTomás sujeta el pomo y la cierra despacio.\n\nNo hace ruido.\n\nAhora puede buscar su cuento.","q":[["¿Por qué cierra despacio?",["Su hermanita duerme","La puerta tiene sueño","No sabe dónde está"],0],["¿Qué busca después?",["Su cuento","Una bicicleta","Un tambor"],0]]},{"id":"d64_es_0_13","grade":0,"t":"La piedra lisa","art":"wood","text":"En el camino hay una piedra lisa.\n\nAlma la mira con su abuelo.\n\nEs gris y cabe en su mano.\n\nLa dejan donde estaba.\n\nAlma dibuja una piedra gris en casa. Ahora tiene un recuerdo.","q":[["¿Cómo es la piedra?",["Lisa y gris","Blanda y roja","De papel"],0],["¿Qué se lleva Alma a casa?",["El recuerdo para dibujarlo","Todas las piedras","El camino"],0]]},{"id":"d64_es_1_01","grade":1,"t":"La visita de la polilla","art":"lamp","text":"Una polilla daba vueltas cerca de la luz del porche. Bruno quiso atraparla, pero su tía le propuso observarla sin tocarla.\n\nSe sentaron en el escalón. Las alas parecían un pequeño abanico. Antes de entrar, apagaron la luz del porche. La polilla se alejó hacia el jardín.\n\nBruno no se llevó ningún animal a casa. Se llevó una imagen que podía dibujar al día siguiente.","q":[["¿Cómo observaron la polilla?",["Sin tocarla","Dentro de un tarro","Persiguiéndola por la calle"],0],["¿Qué hicieron antes de entrar?",["Apagaron la luz","Regaron las alas","Cerraron el jardín con papel"],0]]},{"id":"d64_es_1_02","grade":1,"t":"El pan y la siesta","art":"bread","text":"Sara llevó panecillos a la vecina con su padre. Junto al timbre había un cartel: El bebé está durmiendo.\n\nSara retiró el dedo del botón. Su padre avisó a la vecina con un mensaje y dejaron la cesta en la puerta.\n\nDe vuelta a casa, Sara caminó de puntillas unos pasos. No hacía falta despertar a nadie para dar una alegría.","q":[["¿Por qué no tocaron el timbre?",["El bebé dormía","No había puerta","El pan estaba frío"],0],["¿Qué dejaron en la puerta?",["Panecillos","Una lámpara","Un libro mojado"],0]]},{"id":"d64_es_1_03","grade":1,"t":"Un dibujo del musgo","art":"leaf","text":"Nico vio musgo sobre un muro bajo. Parecía una alfombra diminuta. Lo tocó con cuidado y notó que estaba fresco.\n\nQuiso llevarse un poco. Su abuela le explicó que allí tenía lo que necesitaba para vivir.\n\nNico sacó su libreta. Dibujó manchas verdes y unas piedras. El musgo se quedó en su muro, y Nico pudo recordar su paseo sin llevárselo.","q":[["¿A qué se parecía el musgo?",["A una alfombra pequeña","A una taza","A un zapato"],0],["¿Qué llevó Nico a casa?",["Su dibujo","El muro entero","Una bolsa de musgo"],0]]},{"id":"d64_es_1_04","grade":1,"t":"El pasajero redondo","art":"boat","text":"La barquita de papel de Julia se inclinaba en el agua. Había puesto un botón muy cerca del borde.\n\nJulia lo movió al centro. La barca quedó más derecha. Su hermano hizo aire con un cartón y la barca avanzó por la palangana.\n\nEl botón no tenía ojos ni maleta. Aun así, Julia dijo que era un pasajero muy tranquilo.","q":[["¿Qué ayudó a equilibrar la barca?",["Mover el botón al centro","Poner el botón en el agua","Añadir otro borde"],0],["¿Qué hizo el hermano?",["Abanicar con un cartón","Llenar la barca de tierra","Sacar el botón a pasear"],0]]},{"id":"d64_es_1_05","grade":1,"t":"El lugar de las botas","art":"home","text":"Las botas de Emma dejaban gotas en la entrada. Cada día había que secar el suelo.\n\nEmma encontró una bandeja vieja. Con su madre, comprobó que las dos botas cabían dentro. La puso junto a la puerta.\n\nA la mañana siguiente, las botas volvieron mojadas del paseo. Esta vez las gotas se quedaron en la bandeja. Una cosa pequeña había resuelto un problema diario.","q":[["¿Qué problema había?",["Las botas mojaban el suelo","La puerta no abría","No encontraban los calcetines"],0],["¿Dónde quedaron las gotas al final?",["En la bandeja","En la cama","En la mochila"],0]]},{"id":"d64_es_1_06","grade":1,"t":"El cojín azul","art":"book","text":"En la biblioteca había un cojín grande. Álex se sentó y dejó su mochila al lado.\n\nOtra niña llegó con un cuento y miró el sitio vacío. Álex puso la mochila en el suelo.\n\n—Aquí cabemos —dijo.\n\nCada uno leyó su libro. No hablaron mucho, pero al despedirse acordaron volver a ese rincón. Leer en compañía no siempre significa leer lo mismo.","q":[["¿Cómo dejó sitio Álex?",["Quitó la mochila del cojín","Escondió el libro","Se llevó el cojín a casa"],0],["¿Qué leyó cada uno?",["Su propio libro","La misma página siempre","Una carta del otro"],0]]},{"id":"d64_es_1_07","grade":1,"t":"El trocito de pan","art":"bread","text":"A Dani no le apetecía el extremo de la barra de pan. Le parecía demasiado duro.\n\nSu abuelo lo cortó en dados y los tostó en el horno. Dani los puso sobre la crema de verduras.\n\nAl morderlos, oyó un pequeño crujido. Pidió unos pocos más.\n\nEl trozo que había dejado a un lado acabó siendo lo que más le gustó de la cena.","q":[["¿En qué se convirtió el pan?",["En dados tostados","En una cuchara","En una planta"],0],["¿Con qué lo comieron?",["Con crema de verduras","Con tierra","Con papel"],0]]},{"id":"d64_es_1_08","grade":1,"t":"El paseo del caracol","art":"snail","text":"Un caracol cruzaba el sendero mojado. Mario paró junto a su madre para no pisarlo.\n\nEsperaron a que llegara a una hoja. Tardó bastante, pero nadie tenía que empujarlo.\n\nMario miró los cuernos y la casa que llevaba a cuestas. Cuando el camino quedó libre, siguieron andando.\n\nEl paseo fue un poco más lento. También tuvo algo nuevo que contar.","q":[["¿Por qué se detuvieron?",["Para no pisar al caracol","Para buscar una pelota","Para cerrar el sendero"],0],["¿Quién empujó al caracol?",["Nadie","Mario","Su madre"],0]]},{"id":"d64_es_1_09","grade":1,"t":"Las dos macetas","art":"flower","text":"Lucía plantó dos judías. Una maceta estaba junto a la ventana. La otra quedaba detrás de una caja.\n\nLes dio la misma cantidad de agua. Con los días, la planta escondida se veía más pálida.\n\nLucía retiró la caja para que las dos recibieran luz. Luego dibujó las hojas nuevas. Ahora sabía que regar no era el único cuidado que necesitaban.","q":[["¿Qué les faltaba a las hojas pálidas?",["Más luz","Más cajas","Menos espacio"],0],["¿Qué hizo Lucía?",["Quitó la caja","Tapó las dos macetas","Cortó todas las hojas"],0]]},{"id":"d64_es_1_10","grade":1,"t":"El mar de hoy","art":"palette","text":"A Iván se le terminó la pintura azul cuando iba a pintar el mar. Miró por la ventana: el día estaba gris.\n\nMezcló blanco con una gotita de negro. Pintó un mar gris y una ola verde.\n\nSu hermana dijo que parecía un mar de invierno. Iván dejó secar el cuadro junto a la ventana. No era el mar que había pensado, pero era un mar posible.","q":[["¿Por qué cambió de color?",["No quedaba pintura azul","Había perdido el papel","El pincel no servía"],0],["¿Cómo quedó su mar?",["Gris con una ola verde","Rojo con lunares","Sin pintar"],0]]},{"id":"d64_es_1_11","grade":1,"t":"El sol de papel","art":"paper","text":"Vera dibujó un sol para dejarlo en la mesa de su hermano. Dobló el papel, pero una corriente lo tumbó.\n\nProbó a doblar una base pequeña. Ahora el dibujo se mantenía de pie.\n\nCuando llegó su hermano, añadió una nube al lado del sol. Los dos dibujos se quedaron en la mesa, sujetos por sus pequeños pliegues.","q":[["¿Qué ayudó al papel a mantenerse en pie?",["Una base doblada","Un vaso de leche","Una cuerda larga"],0],["¿Qué añadió el hermano?",["Una nube","Una bota","Una casa de verdad"],0]]},{"id":"d64_es_1_12","grade":1,"t":"La mochila en el autobús","art":"bus","text":"Clara se sentó junto a su padre. Dejó la mochila en el asiento de enfrente.\n\nEn la siguiente parada subió un señor con bastón. Clara cogió la mochila y la puso sobre sus rodillas.\n\nEl señor se sentó y le dio las gracias. Clara miró el paisaje. Su mochila seguía cerca, y otra persona podía viajar sentada.","q":[["¿Para qué movió la mochila?",["Para dejar libre un asiento","Para esconder la ventana","Para bajar del autobús"],0],["¿Dónde puso la mochila?",["Sobre sus rodillas","En la calle","Encima del conductor"],0]]},{"id":"d64_es_1_13","grade":1,"t":"La bufanda corta","art":"bow","text":"La bufanda de Omar ya no le daba dos vueltas al cuello. Él había crecido.\n\nSu tía propuso cerrarla con un lazo de tela, sin apretarla. Así seguía abrigando durante los paseos cortos.\n\nOmar eligió una tela de rayas. La bufanda parecía distinta, pero conservaba su tacto suave. No todo lo que se queda pequeño tiene que dejar de servir de inmediato.","q":[["¿Por qué parecía más corta la bufanda?",["Omar había crecido","La habían cortado","Se había convertido en papel"],0],["¿Qué eligió Omar?",["Una tela de rayas","Una nueva casa","Un zapato azul"],0]]},{"id":"d64_es_1_14","grade":1,"t":"El charco del patio","art":"rain","text":"Después de llover quedó un charco junto al banco. Eva vio el cielo reflejado en el agua.\n\nSu hermano quería saltar. Eva le pidió que esperara un momento para ver la nube entera.\n\nDespués saltaron con las botas puestas y un adulto cerca. La nube se rompió en ondas. Al quedarse quieta el agua, el cielo volvió a aparecer.","q":[["¿Qué veía Eva en el charco?",["El cielo reflejado","Un pez de colores","Una ventana abierta"],0],["¿Qué pasó al calmarse el agua?",["Volvió a verse el cielo","El charco se hizo de piedra","La nube cayó al suelo"],0]]},{"id":"d64_es_1_15","grade":1,"t":"La caja de colores","art":"pencil","text":"La clase tenía una caja de lápices cortos. Algunos niños ya no los elegían.\n\nAina probó uno para dibujar semillas pequeñas. Le resultó cómodo sujetarlo cerca del papel.\n\nPuso los lápices en un bote bajo para que todos se vieran. Enseguida otros niños los usaron para detalles.\n\nLos lápices no habían crecido. Ahora era más fácil descubrir para qué servían todavía.","q":[["¿Para qué usó Aina un lápiz corto?",["Para dibujar semillas pequeñas","Para medir una puerta","Para remover sopa"],0],["¿Qué cambió en el bote bajo?",["Los lápices se veían mejor","Los lápices se hicieron largos","Desaparecieron los colores"],0]]},{"id":"d64_es_1_16","grade":1,"t":"El cuento de la silla","art":"wood","text":"La abuela dejó una silla junto a la ventana. Dijo que era su lugar para contar cuentos.\n\nTeo quiso sentarse en sus rodillas, pero hoy la abuela tenía una pierna dolorida. Acercó otra silla y se sentó a su lado.\n\nEl cuento empezó igual. Teo podía ver sus manos dibujando el tamaño del dragón en el aire.\n\nA veces cambia el sitio, pero no las ganas de estar juntos.","q":[["¿Por qué Teo usó otra silla?",["A la abuela le dolía una pierna","No quería oír el cuento","La ventana estaba cerrada"],0],["¿Qué hicieron juntos?",["Escuchar y contar un cuento","Mover la casa","Plantar un árbol"],0]]},{"id":"d64_es_2_01","grade":2,"t":"El mapa de los armarios","art":"paper","text":"En el local del barrio, nadie encontraba los vasos medidores. Cada persona los guardaba en un sitio. Elena propuso poner nombres en las puertas, pero su hermano pequeño aún no sabía leerlos.\n\nDibujaron un vaso en el armario y una cuchara en el cajón. Usaron líneas oscuras para que los dibujos se vieran bien. La siguiente tarde de cocina, el hermano encontró lo que necesitaba sin preguntar.\n\nEl mapa no tenía calles. Ayudaba a todos a participar en una tarea compartida.","q":[["¿Por qué eligieron dibujos?",["No todos podían leer los nombres","Los armarios estaban en la calle","No quedaba papel"],0],["¿Qué pudo hacer el hermano?",["Encontrar los utensilios","Cambiar el nombre del barrio","Cocinar sin ningún adulto"],0]]},{"id":"d64_es_2_02","grade":2,"t":"El agua que sobraba","art":"rain","text":"El depósito del huerto recogía agua del tejado. Cuando se llenaba, el agua caía junto al escalón y dejaba el suelo resbaladizo.\n\nCon ayuda de una adulta, Pablo llevó la manguera del rebosadero hasta unos arbustos. Durante la siguiente lluvia miraron desde la ventana. El escalón quedó más seco y la tierra de los arbustos se oscureció.\n\nEl depósito seguía guardando agua para otros días. La que sobraba ya no estorbaba en el paso: encontraba un lugar donde hacía falta.","q":[["¿Qué problema causaba el agua sobrante?",["Mojaba un lugar de paso","Secaba el depósito","Cerraba la ventana"],0],["¿Adónde la dirigieron?",["Hacia los arbustos","Al salón","De nuevo al tejado"],0]]},{"id":"d64_es_2_03","grade":2,"t":"Dos lunas para leer","art":"moon","text":"Marta recortó una luna de cartulina para marcar la página de su libro. Una amiga quiso otra, pero solo quedaba un trozo de cartulina plateada.\n\nMarta decidió hacer dos lunas más pequeñas. Una quedó fina, como una uña; la otra, casi redonda. Su amiga eligió la fina.\n\nAl abrir los libros, asomaban dos lunas distintas. No habían salido iguales al primer modelo, pero las dos cumplían su tarea. Marta descubrió que cambiar el tamaño podía ser una forma de compartir.","q":[["¿Cómo aprovechó la cartulina que quedaba?",["Hizo lunas más pequeñas","La tiró","Tapó los libros"],0],["¿Para qué servían las lunas?",["Para marcar páginas","Para iluminar la calle","Para medir la mesa"],0]]},{"id":"d64_es_2_04","grade":2,"t":"El ruido de la estantería","art":"bell","text":"Por la noche, la estantería de Diego hacía un pequeño chasquido. Él pensaba que tal vez había un ratón escondido.\n\nSu madre se quedó a escuchar. El sonido apareció poco después de apagar la lámpara caliente. Le explicó que algunos materiales se mueven un poquito al enfriarse.\n\nLa noche siguiente comprobaron cuándo sonaba. Ocurrió otra vez después de apagar la luz. Diego anotó la observación. La estantería seguía haciendo ruido, pero conocer una explicación le ayudó a descansar.","q":[["¿Cuándo oyeron el chasquido?",["Después de apagar la lámpara","Solo al desayunar","Antes de encender la luz"],0],["¿Qué hicieron para comprobarlo?",["Escucharon otra noche","Compraron un ratón","Vaciaron la casa"],0]]},{"id":"d64_es_2_05","grade":2,"t":"El banco de la entrada","art":"wood","text":"Cuando se rompió el banco del jardín, la gente dejó de pararse junto a la entrada. Daniela echaba de menos las conversaciones de unos minutos.\n\nPreguntó si se podía arreglar. Dos vecinos trajeron herramientas y un adulto revisó las tablas. Daniela ayudó a lijar un borde mientras alguien sujetaba la madera.\n\nAntes de usarlo, comprobaron que el banco estaba firme. Esa tarde, un vecino se sentó con su periódico. Daniela se acercó con un cuento. Habían recuperado un asiento y también un lugar para coincidir.","q":[["¿Qué echaba de menos Daniela?",["Las pequeñas conversaciones","El ruido de los coches","Una puerta más alta"],0],["¿Qué comprobaron antes de sentarse?",["Que el banco estaba firme","Que todos tenían periódico","Que no había flores"],0]]},{"id":"d64_es_2_06","grade":2,"t":"La piedra tibia","art":"sun","text":"En la playa, Andrés encontró una piedra tibia al sol. Otra piedra, bajo la sombrilla, estaba más fresca. Las dos tenían un tamaño parecido.\n\nPuso la primera en la sombra y esperó mientras su padre recogía las cosas. Al volver a tocarla, ya no estaba tan caliente.\n\nDejó las piedras en la playa. En casa podría probar con otras del jardín si las oscuras se calentaban igual que las claras. El paseo le había regalado una pregunta, no una colección de piedras.","q":[["¿Por qué estaba tibia la primera piedra?",["Le daba el sol","Tenía una pila","La habían cocinado"],0],["¿Qué se llevó Andrés?",["Una pregunta para investigar","Todas las piedras","La sombra de la sombrilla"],0]]},{"id":"d64_es_2_07","grade":2,"t":"El puente plegado","art":"bridge","text":"Al poner un coche de juguete sobre una hoja entre dos libros, el papel se hundió. Mar lo retiró y dobló otra hoja como un acordeón.\n\nUsó los mismos libros, a la misma distancia, y el mismo coche. Esta vez el puente aguantó. Mar dibujó las dos pruebas en su libreta.\n\nNo había cambiado el material, sino su forma. Quería contárselo a su prima, así que dejó las dos hojas junto a los dibujos. Así podrían repetir la prueba y ver qué pasaba.","q":[["¿Qué hizo más resistente el puente?",["Los pliegues del papel","Un coche más ligero","Separar mucho más los libros"],0],["¿Por qué usó el mismo coche?",["Para comparar mejor las dos pruebas","Para cambiarle las ruedas","Porque el papel era azul"],0]]},{"id":"d64_es_2_08","grade":2,"t":"Los calcetines que esperan","art":"basket","text":"En casa de Hugo había una cesta de calcetines sin pareja. Su abuelo no decía que estaban perdidos: decía que estaban esperando.\n\nLos ordenaron por tamaño y luego por color. Aparecieron varias parejas. Con los dos últimos hicieron marionetas, usando ojos de tela bien cosidos por un adulto.\n\nEsa tarde las marionetas presentaron un cuento. Algunos calcetines habían encontrado su pareja. Otros habían encontrado una nueva manera de servir. La cesta quedó lista para la próxima colada.","q":[["¿Cómo empezaron a ordenar?",["Por tamaño","Por precio","Por fecha de nacimiento"],0],["¿Qué hicieron con los dos últimos?",["Marionetas","Guantes de cocina","Una nueva cesta"],0]]},{"id":"d64_es_2_09","grade":2,"t":"Un reparto distinto","art":"bread","text":"Tres amigos iban a compartir un pan redondo. Iria cortó dos rebanadas grandes y vio que el último trozo era bastante pequeño.\n\nCortaron las rebanadas en pedazos y los pusieron en el centro. Cada uno eligió un pedazo por turno, sin repetir antes que los demás.\n\nLos montones no quedaron idénticos, pero todos tenían suficiente. Mientras comían, hablaron de hacer panes pequeños la próxima vez. No se trataba de buscar una forma perfecta, sino de fijarse en los demás y ponerse de acuerdo.","q":[["¿Qué notó Iria al cortar?",["El último trozo era menor","Había tres panes","El pan estaba vacío"],0],["¿Cómo continuaron el reparto?",["Eligiendo por turnos","Dejando todo a una persona","Escondiendo los pedazos"],0]]},{"id":"d64_es_2_10","grade":2,"t":"La biblioteca de hojas","art":"leaf","text":"Celia recogía hojas caídas para conocer los árboles de su calle. No arrancaba las que seguían en las ramas. Su tío le ayudó a consultar una guía.\n\nDespués de prensarlas entre papeles, hicieron fichas con la forma de cada hoja, el nombre del árbol y el lugar donde la habían encontrado.\n\nCelia llamó a la caja su biblioteca de hojas. En invierno podía abrirla y recordar el paseo. Cuando llegara la primavera, buscaría las primeras yemas de aquellos mismos árboles.","q":[["¿Qué hojas recogía Celia?",["Las que ya habían caído","Todas las de una rama","Solo hojas de plástico"],0],["¿Qué anotaban en las fichas?",["El nombre del árbol y el lugar","El nombre de cada coche","La hora de la cena"],0]]},{"id":"d64_es_2_11","grade":2,"t":"El buzón de las flores","art":"paper","text":"En el portal pusieron un buzón para dejar mensajes amables. Un lunes, Raúl encontró uno: Tus flores alegran mi paseo. No tenía firma.\n\nComo no sabía a quién responder, dejó una nota para todos: Esta semana se abren las amarillas. Podéis mirarlas desde el camino.\n\nDías después, alguien añadió un dibujo de esas flores. Raúl no llegó a descubrir quién había escrito la primera nota. Tampoco hacía falta. El buzón les permitía conversar sin llamar a ninguna puerta ni pedir nada a cambio.","q":[["¿Por qué no respondió a una persona concreta?",["La nota no llevaba firma","El buzón no abría","No conocía el color amarillo"],0],["¿Qué apareció junto a su respuesta?",["Un dibujo de las flores","Una llave nueva","Un mapa del metro"],0]]},{"id":"d64_es_2_12","grade":2,"t":"Tres sombras","art":"tree","text":"A primera hora, Alba dibujó con tiza la sombra del árbol del patio. Al mediodía, la sombra ya no encajaba en la línea. Hizo otra marca de distinto color.\n\nEl árbol no se había movido de sitio. El sol aparecía en otra posición y la sombra cambiaba de dirección y tamaño.\n\nAntes de merendar, Alba trazó una tercera silueta. Las tres líneas le enseñaban algo que una sola mirada no podía mostrar: el mismo patio cambiaba a lo largo del día.","q":[["¿Qué cambió durante el día?",["La sombra","El lugar de las raíces","El nombre del árbol"],0],["¿Para qué usó varios colores?",["Para distinguir los trazados","Para alimentar al árbol","Para secar la lluvia"],0]]},{"id":"d64_es_2_13","grade":2,"t":"La costura azul","art":"bow","text":"La bolsa favorita de Simón tenía un pequeño desgarro. Él pensaba que tendría que dejar de usarla.\n\nSu abuela cerró la rotura y reforzó el borde con una cinta. Simón eligió hilo azul para que la costura se viera. No quería fingir que la bolsa nunca se había roto.\n\nEn la biblioteca, una amiga se fijó en el dibujo que formaba el hilo. Simón le contó cómo la habían arreglado. La bolsa seguía siendo la misma, pero ahora tenía otra historia que acompañaba a sus libros.","q":[["¿Para qué servía la cinta?",["Para reforzar el borde","Para cerrar la biblioteca","Para hacer más libros"],0],["¿Por qué eligió hilo azul visible?",["Le gustaba mostrar el arreglo","Quería esconder la bolsa","No iba a usarla más"],0]]},{"id":"d64_es_2_14","grade":2,"t":"La sombra prestada","art":"home","text":"En verano, la entrada del local del barrio recibía mucho sol. La gente esperaba fuera mientras se preparaban las mesas.\n\nEva propuso mover unas sillas a la sombra de un árbol cercano. Antes de hacerlo, comprobaron que no bloqueaban el camino ni la puerta. Una vecina llevó una jarra de agua para quien quisiera.\n\nNo habían cambiado el edificio ni comprado nada. Habían mirado con atención lo que ya tenían. Durante la espera, algunos vecinos que apenas se saludaban empezaron a contarse cómo iba su día.","q":[["¿Qué propuso Eva?",["Usar la sombra de un árbol","Cerrar el local todo el verano","Poner las sillas en la puerta"],0],["¿Qué comprobaron primero?",["Que el paso quedaba libre","Que todos vestían igual","Que el árbol era de plástico"],0]]},{"id":"d64_es_2_15","grade":2,"t":"La ventana del tren","art":"bus","text":"En el tren, Omar dibujó el paisaje. Cada vez que terminaba una casa, ya había aparecido otra distinta. Se estaba enfadando con su lápiz.\n\nSu padre le sugirió dibujar solo algunas formas: una torre, una colina, tres árboles. Omar dejó espacios entre ellas. Ya no intentaba copiarlo todo.\n\nAl llegar, miró la página. No era un mapa exacto, pero le recordaba el viaje. Había aprendido que un dibujo también puede guardar lo que elegimos mirar, sin atrapar cada detalle.","q":[["¿Por qué le costaba terminar el dibujo?",["El paisaje cambiaba mientras avanzaban","El tren no tenía ventanas","No quedaban árboles"],0],["¿Qué solución encontró?",["Elegir algunas formas","Dibujar todas las casas a la vez","Tirar el lápiz"],0]]},{"id":"d64_es_2_16","grade":2,"t":"La cena del jardín","art":"apple","text":"La clase recogió seis tomates maduros del huerto. No alcanzaban para que cada niño se llevara uno a casa.\n\nLa maestra propuso cortarlos para una ensalada que compartirían todos. Un adulto usó el cuchillo y los niños lavaron las hojas y prepararon los platos.\n\nCada cual encontró unos trocitos de tomate en su ración. A Noa le supieron distintos de los comprados: recordaba haber regado aquellas plantas. La cosecha era pequeña, pero podían celebrarla sin dejar a nadie fuera.","q":[["¿Por qué hicieron una ensalada?",["Había pocos tomates para repartir enteros","Los tomates eran de papel","Nadie quería probarlos"],0],["¿Qué recordó Noa al comer?",["Que había regado las plantas","Que no había huerto","Que la cena era un dibujo"],0]]},{"id":"d64_es_3_01","grade":3,"t":"El silencio del piano","art":"piano","text":"A Teresa le gustaban las notas rápidas, pero se saltaba los silencios de su partitura. Le parecía que allí no ocurría nada.\n\nSu profesor tocó la melodía de dos maneras. Primero corrió de principio a fin. Después respetó cada pausa. Teresa notó que la segunda versión parecía respirar.\n\nEn casa marcó los silencios con pequeñas nubes de lápiz. Su hermano siguió las nubes mientras ella tocaba. Al acabar, esperaron a que la última nota se desvaneciera antes de hablar.\n\nTeresa no había aprendido una nota nueva. Había aprendido a dejar sitio a lo que venía entre una y otra.","q":[["¿Qué aportaban los silencios?",["Ayudaban a dar forma a la música","Eran errores que debía borrar","Hacían que el piano se apagara"],0],["¿Para qué dibujó nubes?",["Para recordar las pausas","Para tapar las notas difíciles","Para anunciar una tormenta"],0]]},{"id":"d64_es_3_02","grade":3,"t":"El mapa de la sombra","art":"tree","text":"Los bancos del patio estaban muy calientes después de comer. Unai propuso plantar un árbol, pero no sabía dónde convendría hacerlo.\n\nDurante varios días, la clase marcó en un plano las sombras de la mañana y de la tarde. Un banco que estaba fresco temprano quedaba luego al sol. La jardinera usó sus dibujos para explicar qué árboles podrían vivir bien allí.\n\nMientras preparaban la plantación, trasladaron un banco bajo un toldo que ya existía. Unai comprendió que podían buscar una solución para el futuro y otra para ese mismo día. Observar había sido el primer trabajo, aunque al principio no pareciera un trabajo.","q":[["¿Por qué miraron el patio a distintas horas?",["La sombra cambiaba de lugar","Los bancos caminaban","El plano cambiaba solo"],0],["¿Qué ayudó de inmediato?",["Mover un banco bajo el toldo","Esperar a que el árbol creciera en una noche","Pintar el suelo de verde"],0]]},{"id":"d64_es_3_03","grade":3,"t":"Puntadas para leer","art":"bow","text":"La manta del rincón de lectura tenía una costura abierta. Candela quiso arreglarla, pero sus primeras puntadas salieron desiguales. Sacó el hilo y empezó de nuevo dos veces.\n\nSu tía le dio un retal para practicar sin estropear la manta. Candela hizo unas pocas puntadas despacio. Al relajar los hombros, sus manos trabajaban mejor.\n\nCuando volvió a la manta, la costura no quedó perfecta, pero sujetaba bien la tela. Al día siguiente, dos niños se taparon las piernas con ella para escuchar un cuento. Nadie midió las puntadas. Candela se sentó cerca y sintió el calor de algo que había ayudado a cuidar.","q":[["¿Para qué servía el retal?",["Para practicar antes de coser la manta","Para esconder el agujero","Para fabricar una aguja"],0],["¿Qué consiguió la costura?",["Que la manta volviera a servir","Que todos los puntos fueran invisibles","Que la manta creciera sola"],0]]},{"id":"d64_es_3_04","grade":3,"t":"Una tormenta muy ruidosa","art":"rain","text":"La lluvia golpeó con fuerza el tejadillo metálico. Darío aseguró que nunca había llovido tanto aquel mes. Su hermana señaló el pluviómetro del jardín.\n\nCuando terminó la tormenta, comprobaron la altura del agua. Había menos que después de una lluvia suave y larga de la semana anterior. El ruido del tejado había sido una pista engañosa.\n\nDarío anotó su primera impresión junto a la medida. No la borró por haberse equivocado. Le ayudaría a recordar que una tormenta puede sonar enorme y durar poco. La siguiente vez escucharía el agua con la misma curiosidad, pero esperaría a medirla antes de comparar.","q":[["¿Por qué el ruido no bastaba para comparar?",["No indicaba la cantidad total de lluvia","El agua no podía medirse","El jardín estaba cubierto"],0],["¿Qué hizo Darío con su primera idea?",["La anotó junto a la medida","La convirtió en una regla","Dejó de observar la lluvia"],0]]},{"id":"d64_es_3_05","grade":3,"t":"La ventana del rellano","art":"home","text":"En el rellano había una ventana con un alféizar vacío. Berta propuso poner plantas. Un vecino temía que al regarlas goteara agua sobre las escaleras.\n\nEn vez de discutir, Berta dibujó dos macetas dentro de bandejas profundas. Otra vecina ofreció plantas que necesitaban poca luz. Hicieron un pequeño turno de riego y probaron el plan durante un mes.\n\nLas bandejas recogían las gotas. La gente se detenía a mirar las hojas nuevas y a comentar quién había regado. La ventana no pertenecía a nadie en particular. Cuidarla juntos la convirtió en un lugar donde era más fácil saludarse.","q":[["¿Cómo respondió Berta a la preocupación?",["Buscó una forma de recoger las gotas","Ignoró al vecino","Tapó las escaleras"],0],["¿Para qué hicieron turnos?",["Para compartir el cuidado","Para impedir que crecieran hojas","Para contar ventanas"],0]]},{"id":"d64_es_3_06","grade":3,"t":"El cajón de postales","art":"paper","text":"Marina encontró un cajón lleno de postales de su abuelo. Quiso ordenarlas por ciudades. Él sugirió agruparlas también según la persona que las había enviado.\n\nAl hacer montones por lugares, aparecía un mapa de viajes. Al reunir las de una misma persona, se notaban otros cambios: una letra que se hacía más firme, una nueva dirección, una despedida repetida cada verano.\n\nMarina preparó dos listas para poder buscar de las dos maneras. No habían añadido ninguna postal, pero el cajón contaba ahora más de una historia. Su abuelo dejó una sobre la mesa. Mostraba una calle corriente donde había vivido una amiga muy querida.","q":[["¿Qué permitía ver el orden por remitentes?",["Cambios en la vida de las personas","Solo el precio de los sellos","El peso del cajón"],0],["¿Por qué Marina hizo dos listas?",["Las dos formas de ordenar aportaban algo","Una lista no tenía palabras","Quería tirar las postales"],0]]},{"id":"d64_es_3_07","grade":3,"t":"Un jardín al anochecer","art":"flower","text":"Algunas flores del huerto abrían cuando empezaba a oscurecer. Irene quería poner más luces para verlas mejor. La jardinera le enseñó una polilla que se acercaba a una flor pálida.\n\nLe explicó que algunos visitantes nocturnos podían desorientarse con demasiada luz. Irene cambió su idea. Diseñó un cartel que invitaba a mirar desde el camino, en silencio y antes de cerrar el jardín.\n\nDibujó unas alas sobre una flor, sin pedir a nadie que atrapara animales. Aquella tarde observó una polilla sin encender la linterna. Ver mejor no siempre consistía en iluminar más. A veces ayudaba esperar y acostumbrar los ojos a la tarde.","q":[["¿Por qué reconsideró las luces?",["Podían molestar a visitantes nocturnos","Las flores eran de papel","Las polillas necesitaban pantallas"],0],["¿Qué invitaba a hacer el cartel?",["Observar con calma desde el camino","Recoger todas las polillas","Entrar después del cierre"],0]]},{"id":"d64_es_3_08","grade":3,"t":"La lata sin tapa","art":"cup","text":"Una lata de galletas había perdido su tapa. Ya no mantenía las galletas crujientes, y Félix pensó que tocaría reciclarla.\n\nEn el taller vio que los lápices rodaban por la mesa. Forró el fondo de la lata con fieltro y los colocó dentro. Como la base pesaba, el bote no se volcaba con facilidad. Dibujó un lápiz fuera para indicar su nuevo uso.\n\nTodavía se veía una esquina de la antigua etiqueta de galletas. No importaba. La lata no había vuelto a ser nueva ni había recuperado la tapa. Había encontrado una tarea para la que la tapa no hacía falta.","q":[["¿Por qué ya no guardaba bien las galletas?",["Le faltaba la tapa","Era demasiado baja para la mesa","No tenía dibujos"],0],["¿Qué ayudaba a que no se volcara?",["Su base pesada","Los lápices rodando fuera","El dibujo de una galleta"],0]]},{"id":"d64_es_3_09","grade":3,"t":"Un paseo hecho de sonidos","art":"ear","text":"Ariadna dibujó un mapa de su paseo sin escribir calles. Puso curvas donde sonaba la fuente, puntos para los pájaros y una línea torcida junto a la verja que chirriaba.\n\nCreyó que el rincón más silencioso quedaría en blanco. Sin embargo, allí oyó el roce de las hojas y un autobús muy lejano. Añadió dos marcas diminutas.\n\nEn casa, su hermano siguió el mapa mientras ella describía lo que había escuchado. El silencio no había dejado vacío aquel lugar. Les había permitido notar sonidos pequeños que normalmente pasaban por alto. La próxima vez, el hermano quería acompañarla y añadir sus propias marcas.","q":[["¿Qué representaban las marcas del mapa?",["Sonidos del paseo","Números de edificios","Colores de zapatos"],0],["¿Qué descubrió en el rincón tranquilo?",["Podía oír sonidos más pequeños","No existía ningún sonido","La fuente estaba dentro del autobús"],0]]},{"id":"d64_es_3_10","grade":3,"t":"La cuchara del invierno","art":"wood","text":"Para una exposición escolar, cada alumno llevó un objeto con historia. Joel eligió una cuchara de madera y al principio se sintió un poco decepcionado: otros habían traído cosas más llamativas.\n\nSu padre le contó que tres generaciones habían removido con ella la sopa de invierno. Una parte del mango estaba oscura por el uso y un golpe antiguo había dejado una marca.\n\nJoel escribió pequeñas etiquetas para explicar esas señales. No intentó borrarlas. En la exposición, varias personas se acercaron a leer. La cuchara no había viajado por palacios. Había pasado de mano en mano, preparando comidas y reuniendo a la familia alrededor de una mesa.","q":[["¿Por qué dejó visibles las marcas?",["Ayudaban a contar la historia","No quería mostrar la cuchara","Las etiquetas eran demasiado grandes"],0],["¿Qué hacía especial el objeto?",["Su uso a lo largo de varias generaciones","Que fuera de oro","Que cocinara sin ayuda"],0]]},{"id":"d64_es_3_11","grade":3,"t":"La cerca con huecos","art":"wood","text":"La clase probó dos barreras para proteger un jardín de papel del viento de un ventilador. Una era una pared lisa de cartón. La otra, una cerca con pequeños espacios.\n\nMantuvieron la misma velocidad del ventilador y la misma distancia. Detrás de la pared el aire casi no se movía, pero en los lados agitaba mucho las hojas. La cerca dejaba pasar una corriente más suave.\n\nRepitieron la prueba antes de elegir. Sabían que un modelo no explicaba todo lo que ocurriría en un jardín real. Aun así, les ayudó a comparar ideas sin decidir solamente por cuál parecía más fuerte a simple vista.","q":[["¿Qué mantuvieron igual?",["La velocidad del ventilador y la distancia","La forma de las barreras","El número de huecos"],0],["¿Para qué repitieron la prueba?",["Para comprobar si el resultado se repetía","Para gastar el cartón","Para cambiar el nombre del viento"],0]]},{"id":"d64_es_3_12","grade":3,"t":"La última página","art":"book","text":"A la libreta de Nerea le quedaba una sola página. La reservó para un dibujo extraordinario y durante varios paseos no dibujó nada.\n\nUna tarde se fijó en una gota colgada de un tallo. Dentro se veía el jardín del revés. Nerea dibujó la curva del tallo y aquel pequeño reflejo.\n\nAl llegar a casa, comprendió que esperar algo perfecto le había impedido mirar con atención lo que tenía delante. Escribió la fecha bajo el dibujo y cerró la libreta llena. El jardín no se había terminado. Al contrario: tenía ganas de empezar otra libreta para seguir descubriéndolo.","q":[["¿Por qué había guardado la página?",["Esperaba un tema extraordinario","Había perdido todos los lápices","No le gustaba el jardín"],0],["¿Qué acabó dibujando?",["Una gota en un tallo","Un castillo enorme","Una página en blanco"],0]]},{"id":"d64_es_3_13","grade":3,"t":"La linterna de papel","art":"lamp","text":"En la fiesta del barrio, Abril llevaba una linterna de papel con una lucecita de pilas. Su hermano menor sujetaba una cinta de su chaqueta para caminar a su lado.\n\nUna ráfaga soltó el asa de cartón. Abril se apartó del paso y pidió ayuda. Una vecina tenía una pinza grande y sujetó el asa sin tapar la luz.\n\nAbril no necesitó una linterna nueva. Siguió el paseo con una pequeña reparación a la vista. Al final, dibujó la pinza en su cuaderno. Quería recordar que aquella noche también había brillado la ayuda de alguien que se detuvo un momento.","q":[["¿Qué problema tuvo la linterna?",["Se soltó el asa","Se convirtió en una vela","No tenía papel"],0],["¿Cómo ayudó la vecina?",["Sujetó el asa con una pinza","Encendió una hoguera","Se llevó la linterna"],0]]},{"id":"d64_es_3_14","grade":3,"t":"El robot de las macetas","art":"robot","text":"El pequeño robot del taller podía llevar macetas de un lado a otro. Su primer recorrido fue muy rápido y dejó un rastro de tierra sobre la mesa.\n\nLa clase revisó la ruta. Había un giro demasiado cerrado y un bache formado por dos tablas. Ajustaron el programa para que redujera la velocidad y cambiaron el paso por una superficie lisa.\n\nEn la siguiente prueba, la maceta llegó entera y casi no perdió tierra. Julia anotó las dos modificaciones. No bastaba con decir que el robot era torpe: tenían que averiguar qué parte del recorrido necesitaba cuidado. Trabajar más despacio había permitido trabajar mejor.","q":[["¿Qué hicieron antes de repetir?",["Revisaron el recorrido y los ajustes","Pintaron la tierra","Quitaron todas las macetas del mundo"],0],["¿Qué mostró la segunda prueba?",["Que ir más despacio podía ayudar","Que los robots no pueden girar nunca","Que la tierra pesaba menos por la tarde"],0]]},{"id":"d64_es_3_15","grade":3,"t":"Las voces bajo el agua","art":"whale","text":"En una charla del acuario, Manu escuchó grabaciones de cachalotes. No sonaban como una canción con palabras. Eran secuencias de clics, con pausas y ritmos diferentes.\n\nLa investigadora explicó que los grupos de cachalotes comparten maneras de comunicarse y que las crías necesitan aprenderlas. Los científicos estudian esas señales, pero todavía no pueden traducirlas como si fueran frases humanas.\n\nManu dibujó puntos y espacios para representar dos secuencias que había oído. Debajo escribió: Escuchar no significa entenderlo todo. Aquella idea le gustó. Permitía sentir curiosidad sin inventar una respuesta antes de tener pruebas.","q":[["¿Qué oyó Manu?",["Secuencias de clics","Palabras humanas claras","Solo silencio"],0],["¿Qué reconoció sobre la investigación?",["Aún quedan cosas por comprender","Ya se traduce cualquier frase","Los cachalotes no aprenden nada"],0]]},{"id":"d64_es_3_16","grade":3,"t":"La espiral del sendero","art":"paper","text":"Valeria encontró en un libro un dibujo antiguo de una ruta. Marcaba una roca con una espiral cerca de un sendero conocido. Fue a buscarla con su padre, llevando agua y siguiendo los caminos señalados.\n\nEncontraron la roca sin salir de la ruta. Junto a la espiral había una fecha de hacía muchos años. No era un cofre ni una pista para llevarse un tesoro.\n\nValeria hizo una fotografía y no tocó la marca. En casa dibujó su propia espiral en papel. Le gustaba pensar que otras personas también podrían encontrar la roca y sentir la misma curiosidad, sin que ella tuviera que llevarse nada.","q":[["¿Qué hicieron al encontrar la roca?",["Observarla y fotografiarla sin tocar la marca","Llevársela al colegio","Borrar la fecha"],0],["¿Qué valor tenía el hallazgo?",["Una conexión con quienes estuvieron allí antes","Un premio escondido","Una orden para abandonar el sendero"],0]]},{"id":"d64_es_3_17","grade":3,"t":"El cuaderno de las nubes","art":"cloud","text":"Cuando respiraba junto a la ventana del patio en una mañana fría, Elisa veía una nubecita salir de su boca. Por la tarde, con más calor, ya no se veía igual.\n\nSu maestro explicó que el aire que exhalamos contiene vapor de agua. Al enfriarse, parte puede formar gotitas muy pequeñas que sí vemos. No era humo ni significaba que Elisa estuviera quemando nada.\n\nDurante varios días anotó la temperatura aproximada y si veía la nubecita. Los resultados no eran idénticos cada mañana. La humedad y otras condiciones también influían. Su cuaderno empezó con una sorpresa y terminó lleno de nuevas preguntas.","q":[["¿Qué formaba la nubecita visible?",["Gotitas de agua","Ceniza","Polvo del cuaderno"],0],["¿Por qué anotó varios días?",["Para observar cambios y comparar","Para demostrar que siempre ocurría igual","Para fabricar humo"],0]]},{"id":"d64_es_3_18","grade":3,"t":"Una magdalena para cada uno","art":"bread","text":"En la cocina escolar faltaban tres magdalenas de una bandeja. Leo estuvo a punto de culpar al compañero que había entrado el último. La maestra le propuso revisar primero lo que sabían.\n\nMiraron la lista del reparto y preguntaron a los responsables. Las tres magdalenas ya se habían llevado a otra aula, tal como estaba previsto. Nadie las había cogido a escondidas.\n\nLeo sintió alivio por no haber acusado a nadie. Ayudó a añadir una marca en la lista para indicar los platos entregados. La merienda siguió tranquila. Resolver la duda había requerido menos imaginación y más atención a la información que tenían cerca.","q":[["¿Dónde estaban las magdalenas?",["En otra aula, según el reparto previsto","Dentro del horno apagado","En la mochila de Leo"],0],["¿Qué evitó Leo al comprobar primero?",["Una acusación sin pruebas","Tener que merendar","Leer la lista"],0]]},{"id":"d64_es_3_19","grade":3,"t":"La caminata por tramos","art":"tree","text":"En una excursión con su familia, Ada miró la colina y pensó que estaba demasiado lejos. Su padre no le pidió que corriera ni que dejara de sentirse cansada.\n\nEligieron un punto cercano: una curva junto a un pino. Allí descansarían y decidirían si continuar. Después eligieron otro tramo. Llevaron agua, siguieron la ruta y regresaron antes de que anocheciera.\n\nNo llegaron al mirador más alto, pero vieron un valle que brillaba con la luz de la tarde. Ada lo dibujó en una hoja. Dividir el paseo en partes le había ayudado a disfrutarlo sin convertir la cima en una obligación.","q":[["¿Qué les ayudó a organizar el paseo?",["Elegir tramos y descansos","Correr sin mirar el camino","No llevar agua"],0],["¿Qué decidió la familia sobre la cima?",["No era necesario llegar para disfrutar","Había que llegar a cualquier precio","Solo podían volver de noche"],0]]},{"id":"d64_es_3_20","grade":3,"t":"El día de los globos de papel","art":"paper","text":"En el cuento que inventó la clase, los objetos pesados querían descansar. Las cucharas flotaban sobre los platos y las mochilas subían despacio hasta el techo. Era un mundo imaginario, no una explicación de la gravedad real.\n\nA Samuel le tocó pensar cómo merendarían los personajes. Propuso una mesa con bolsillos para sujetar los cuencos. Su amiga añadió cintas suaves para que las servilletas no se escaparan.\n\nAl terminar, compararon ese mundo con el suyo. Precisamente porque las cosas normalmente caen hacia el suelo, sus inventos resultaban divertidos. La fantasía les había servido para mirar con más atención algo cotidiano que casi nunca notaban.","q":[["¿Cómo se presenta ese mundo?",["Como una invención de la clase","Como una noticia científica","Como un lugar que visitaron ayer"],0],["¿Qué hicieron después de inventarlo?",["Compararlo con el mundo real","Asegurar que ya no existe la gravedad","Tirar todas las cucharas"],0]]},{"id":"d64_es_4_01","grade":4,"t":"Una mesa tranquila","art":"wood","text":"En la tarde de reparaciones de la biblioteca, varias personas hablaban al mismo tiempo. La señora Molina miraba las demostraciones con interés, pero se apartaba cuando aumentaba el ruido. Aina pensó al principio que no quería participar.\n\nAntes de darlo por hecho, le preguntó si le ayudaría una mesa más tranquila. Prepararon un rincón y acordaron explicar un paso cada vez. La señora Molina llevó allí un marco roto y enseñó a Aina a mantener rectas las esquinas mientras se secaba el pegamento.\n\nEl cambio no la había separado del grupo: le había permitido aportar lo que sabía. Aina puso un cartel sencillo, Un lugar tranquilo para trabajar, sin explicar los motivos privados de nadie.","q":[["¿Qué tenía de incompleta la primera impresión de Aina?",["No distinguía entre falta de interés y dificultad con el ruido","La señora no sabía reparar","La biblioteca estaba vacía"],0],["¿Qué permitió la mesa tranquila?",["Participar y compartir una habilidad","Trabajar sin escuchar nunca a otros","Cerrar la actividad al público"],0]]},{"id":"d64_es_4_02","grade":4,"t":"El sobre de las judías","art":"flower","text":"Un sobre del huerto llevaba escrito Judías amarillas de la abuela. Nil quiso cambiar la etiqueta por otra con un nombre más preciso.\n\nLa abuela le pidió conservar el papel antiguo dentro. Aquellas semillas procedían de una vecina que las había compartido con la familia muchos años atrás. La letra era suya.\n\nNil añadió una ficha con la fecha de siembra, la distancia entre plantas y una descripción de las vainas. Una nota servía para cultivar; la otra guardaba una relación entre personas.\n\nAl recoger semillas nuevas en otoño, preparó un sobre para un amigo. Incluyó instrucciones y una breve explicación del nombre. No necesitaba elegir entre un registro útil y un recuerdo: podían viajar juntos.","q":[["¿Por qué conservar la etiqueta antigua?",["Recordaba a la vecina que compartió las semillas","Pesaba más que la nueva","Sin ella no crecería ninguna planta"],0],["¿Qué aportaba la ficha nueva?",["Información para cultivar","Una razón para borrar la historia","Un nombre secreto para la vecina"],0]]},{"id":"d64_es_4_03","grade":4,"t":"El borde del mosaico","art":"pattern","text":"El mosaico del centro vecinal debía tener un borde azul. Al acercarse a la última esquina, faltaron piezas. Comprar más no garantizaba encontrar exactamente el mismo tono.\n\nEl grupo extendió los restos de cerámica sobre una tela. Una niña observó que los verdes y los azules juntos parecían la orilla de un río. Revisaron el diseño para que el cambio de color comenzara poco a poco, no de golpe al final.\n\nVioleta guardó el primer boceto junto a una fotografía del mosaico terminado. Mostraba cómo había cambiado su idea. El nuevo borde no era un fallo escondido: era una decisión compartida, nacida de mirar de otra manera los materiales disponibles.","q":[["¿Qué motivó el cambio de diseño?",["La falta de piezas azules","Una pared demasiado alta","La llegada del invierno"],0],["¿Qué mostraba conservar el boceto?",["Cómo había evolucionado la idea","Que nada había cambiado","Que las piezas nuevas eran invisibles"],0]]},{"id":"d64_es_4_04","grade":4,"t":"El jardín en el cristal","art":"cloud","text":"Un pájaro se acercó al cristal del aula y volvió a una rama. La clase quiso entender qué lo había atraído. Desde fuera, la ventana reflejaba el jardín y parecía una continuación del espacio abierto.\n\nCon su maestra, buscaron información sobre marcas exteriores que ayudan a las aves a distinguir el vidrio. Un adulto colocó un dibujo de puntos próximos entre sí, siguiendo las indicaciones adecuadas.\n\nLos alumnos observaron desde lejos durante varias semanas. No dijeron que todo estuviera resuelto solo porque una tarde no ocurriera nada.\n\nLa ventana seguía dejando entrar luz. También recordaba algo importante: para comprender un problema, a veces hay que mirar desde el lugar de quien lo encuentra, no solamente desde nuestro lado del cristal.","q":[["¿Por qué podía resultar confuso el cristal?",["Reflejaba el jardín como si fuera espacio abierto","Tenía comida pintada","Era una puerta sin marco"],0],["¿Por qué observar durante semanas?",["Una sola tarde no bastaba para evaluar el cambio","Los pájaros solo aparecen una vez al año","Los puntos desaparecían cada noche"],0]]},{"id":"d64_es_4_05","grade":4,"t":"La receta que se podía explicar","art":"bread","text":"Todo el barrio pedía la receta de la sopa de Amparo. Ella conocía los ingredientes, pero calculaba las cantidades a ojo. Su nieto Mateo se ofreció a ayudarla a escribirla.\n\nMidieron cada añadido y anotaron cuándo rectificaba la sal. Una indicación seguía siendo vaga: Cocinar hasta que esté lista. Mateo le preguntó qué señales buscaba. Amparo describió las verduras tiernas y el cambio de aroma del caldo.\n\nLa receta final incluía un tiempo aproximado y esas pistas. No convertía la cocina en una regla rígida; ayudaba a quien empezaba a observar por sí mismo.\n\nEn la siguiente comida compartida, otra vecina preparó la sopa. Amparo pudo sentarse a conversar antes de que llegaran los platos.","q":[["¿Por qué costaba escribir las cantidades?",["Amparo solía calcularlas a ojo","No conocía los ingredientes","Nunca había preparado sopa"],0],["¿Para qué añadieron pistas sobre textura y aroma?",["Para reconocer cuándo estaba lista cada preparación","Para no usar nunca un reloj","Para cambiar el nombre del plato"],0]]},{"id":"d64_es_4_06","grade":4,"t":"Doce fotografías de un árbol","art":"sun","text":"Cada sábado, a la misma hora, Brais fotografió el árbol del patio. Esperaba obtener imágenes casi iguales, pero las sombras y las hojas cambiaron más de lo previsto.\n\nAlgunas diferencias se debían a las nubes; otras, al avance de la primavera. Brais ordenó las fotografías por fecha y añadió las notas del tiempo que había tomado durante el proyecto.\n\nSin esas notas, alguien podía confundir una mañana nublada con un cambio de estación. Las etiquetas ayudaban a separar lo observado de sus posibles explicaciones.\n\nLa exposición ocupó poco espacio, aunque reunía tres meses de atención. Después de montarla, Brais pasó una mañana bajo el árbol sin cámara. No todo lo que disfrutaba necesitaba convertirse en una fotografía.","q":[["¿Por qué añadió datos del tiempo?",["Las nubes explicaban algunas diferencias","El árbol necesitaba leerlos","Las fechas cambiaban el color de las hojas"],0],["¿Qué había reunido el proyecto?",["Observaciones repetidas a lo largo del tiempo","Doce árboles diferentes","Solo una tarde de trabajo"],0]]},{"id":"d64_es_4_07","grade":4,"t":"La cesta de los guantes","art":"basket","text":"Junto a la entrada de la escuela dejaron una cesta con guantes de repuesto. Cualquiera podía tomar un par y devolverlo después. Al cabo de una semana casi no quedaban, y algunos dijeron que el sistema no funcionaba.\n\nZoe propuso averiguar qué había ocurrido. Varios pares habían viajado a casa por descuido. Algunos niños necesitaban quedárselos. Otros no sabían dónde devolverlos.\n\nPusieron una señal más clara e invitaron a las familias a aportar guantes limpios en buen estado. También acordaron que quien necesitara un par podía conservarlo sin explicar su situación delante de todos.\n\nEl objetivo de la cesta no era permanecer llena, sino ayudar a abrigar manos. Comprenderlo cambió su forma de valorar el resultado.","q":[["¿Por qué Zoe pidió comprobar primero?",["La cesta vacía podía tener distintas explicaciones","Quería prohibir los guantes","Nadie había usado la entrada"],0],["¿Qué consideraron un buen resultado?",["Que la cesta ayudara a mantener las manos calientes","Que nadie tomara guantes","Que todos justificaran su necesidad en público"],0]]},{"id":"d64_es_4_08","grade":4,"t":"El estanque del plano","art":"paper","text":"El conserje encontró un plano antiguo del colegio. En el centro del jardín aparecía un estanque; fuera solo quedaba una suave hondonada cubierta de hierba.\n\nHéctor quiso saber si el estanque había llegado a construirse. El plano podía mostrar una intención y no un hecho. Buscó fotografías del archivo y conversó con una antigua maestra. Una imagen mostraba el agua y la maestra recordaba cuándo se había rellenado el hueco.\n\nHéctor hizo una exposición y señaló de dónde procedía cada dato. La hondonada adquirió una historia, pero él aprendió algo más que una fecha: fuentes distintas responden a preguntas distintas, y conviene no pedirle a una sola que cuente todo.","q":[["¿Por qué el plano no era una prueba suficiente?",["Podía representar una obra nunca realizada","Todos los planos eran falsos","La hierba no podía crecer allí"],0],["¿Qué hizo Héctor al presentar los datos?",["Indicó la fuente de cada uno","Inventó los detalles que faltaban","Ocultó la fotografía antigua"],0]]},{"id":"d64_es_4_09","grade":4,"t":"Menos palabras para escuchar","art":"ear","text":"El museo pidió a la clase un cartel para una sala de sonidos. Dalia escribió una explicación detallada de todo lo que se oía: agua, hojas, pasos y ruedas lejanas.\n\nDurante una prueba, su prima pasó la grabación entera leyendo el cartel y apenas escuchó la fuente. Dalia comprendió que la explicación competía con la experiencia.\n\nLa redujo a dos invitaciones breves para observar los sonidos. Dejó los detalles en una ficha aparte, disponible para quien quisiera saber más.\n\nEl cartel no enseñaba menos por ser más corto. Permitía escuchar primero y elegir después qué investigar. Dalia guardó su borrador largo. Quitar palabras había necesitado tanta atención como escribirlas.","q":[["¿Qué problema tenía el primer cartel?",["Distraía de la grabación","No contenía ninguna explicación","Había apagado la fuente"],0],["¿Por qué conservaron una ficha adicional?",["Algunos visitantes querrían más información","Para impedir preguntas","Para sustituir todos los sonidos"],0]]},{"id":"d64_es_4_10","grade":4,"t":"Los hilos del bosque","art":"tree","text":"En un paseo guiado, Marcos vio un hongo junto a un tronco. La guía explicó que aquella parte visible era solo una porción de un organismo mayor. Bajo el suelo se extendían filamentos llamados micelio.\n\nAlgunos hongos se asocian con raíces. Reciben azúcares de la planta y facilitan la llegada de agua y nutrientes. No todos los hongos hacen lo mismo ni todas las relaciones entre árboles están resueltas por la ciencia.\n\nMarcos dibujó la seta sobre el suelo y una red debajo. Puso una línea de puntos donde su dibujo era una simplificación. Le gustó descubrir que una imagen podía ayudar a comprender, siempre que recordara que el bosque real era más complejo que el papel.","q":[["¿Qué representaba la parte visible?",["Solo una parte del hongo","Todo el bosque","Una raíz de plástico"],0],["¿Por qué señaló que el dibujo era sencillo?",["El sistema real tenía más complejidad","No quería explicar nada","El micelio no existía"],0]]},{"id":"d64_es_4_11","grade":4,"t":"La caja de calcetines","art":"basket","text":"En la lavandería del edificio, varias personas habían perdido calcetines. En lugar de suponer que alguien los cogía, Leire propuso revisar el lugar con el encargado.\n\nUn adulto movió la máquina y encontró una abertura junto a una tubería. Allí se habían acumulado calcetines caídos durante meses. Los lavaron y los colgaron en un panel para que sus dueños los reconocieran.\n\nLeire anotó la solución del problema: tapar la abertura y revisar detrás del cesto de vez en cuando. Mostrar los calcetines recuperados era divertido, pero evitar que volvieran a caer resultaba más útil.\n\nA la semana siguiente, el panel estaba casi vacío. Las parejas habían regresado a los cajones de sus casas.","q":[["¿Qué hicieron antes de acusar a nadie?",["Revisaron el lugar con el encargado","Compraron otra lavadora","Cerraron todos los cajones"],0],["¿Qué evitaba que el problema se repitiera?",["Tapar la abertura","Pintar los calcetines","Colgar un panel más grande"],0]]},{"id":"d64_es_4_12","grade":4,"t":"El invierno del albaricoquero","art":"flower","text":"El albaricoquero de la plaza se cubrió de flores temprano. Después llegó una helada y aquel verano hubo muy pocos frutos. Nora pensó que el árbol debía de estar enfermo.\n\nLa jardinera le explicó que las flores son delicadas y que una helada puede dañarlas aunque el árbol sobreviva. Muchos frutales también necesitan un periodo de frío durante el invierno para desarrollar su ciclo con normalidad.\n\nNora anotó las fechas de las flores y de la helada, sin sacar conclusiones de un solo año. Al pasar por la plaza seguía viendo hojas sanas y sombra.\n\nUn verano con poca fruta no contaba toda la historia del árbol. Había que observarlo durante más tiempo.","q":[["¿Qué dañó las flores?",["Una helada posterior a la floración","El dibujo de Nora","La sombra del verano"],0],["¿Por qué mirar más de un año?",["Una temporada no explicaba toda la situación","Los árboles cambiaban de especie","La fruta nunca depende del tiempo"],0]]},{"id":"d64_es_4_13","grade":4,"t":"La radio del estante","art":"speaker","text":"La radio antigua llevaba años sin sonar. Aun así, el abuelo de Celia le quitaba el polvo cada domingo. Ella entendió que aquel objeto debía de significar algo para él.\n\nPreguntó si le gustaría repararlo. Con su permiso, buscaron a un técnico del barrio; no abrieron el aparato por su cuenta. Tras varias visitas, el técnico encontró dos piezas dañadas y explicó el arreglo.\n\nCuando volvió a sonar una melodía, el abuelo reconoció una canción de su juventud. Celia no había recuperado todos sus recuerdos, pero le había dado una ocasión para compartir uno.\n\nSe sentaron junto a la radio sin llenar cada pausa con preguntas. A veces escuchar también es una manera de acompañar.","q":[["¿Qué le hizo pensar que la radio importaba?",["El abuelo seguía cuidándola","Era el objeto más nuevo","Nadie sabía de quién era"],0],["¿Cómo buscaron una reparación segura?",["Acudieron a un técnico","La abrieron sin ayuda","La pusieron bajo el agua"],0]]},{"id":"d64_es_4_14","grade":4,"t":"El bambú del puente","art":"wood","text":"En una exposición de materiales, Saúl se sorprendió al ver bambú usado para construir. Le parecía un árbol, pero la explicación lo describía como una gramínea: un tipo de hierba.\n\nSus tallos huecos pueden ser ligeros y resistentes. En distintos lugares se emplean en estructuras, aunque elegirlos y tratarlos bien es importante. La humedad, los insectos y una preparación inadecuada pueden debilitarlos.\n\nSaúl comparó varias muestras y dibujó un corte del tallo. No escribió que cualquier bambú sirviera para cualquier edificio. Escribió que un material útil necesita conocimientos adecuados para usarse con seguridad.\n\nLa visita le dejó una idea tranquila y amplia: a veces una planta conocida tiene posibilidades que solo descubrimos al mirarla con otras preguntas.","q":[["¿Qué aprendió sobre el bambú?",["Es una gramínea","Es una piedra hueca","No es una planta"],0],["¿Por qué importa su preparación?",["Influye en la seguridad y la resistencia","Le cambia el nombre","Evita que alguna vez crezca"],0]]},{"id":"d64_es_4_15","grade":4,"t":"El pase de Martina","art":"ball","text":"Quedaba poco tiempo de partido y el balón llegó a Martina. Podía lanzar desde lejos o pasárselo a Elías, que estaba mejor colocado. Elías todavía no había marcado aquella temporada.\n\nMartina le pasó el balón. Él se acomodó, tiró y consiguió el gol. Más tarde le preguntó por qué había confiado en él si había fallado tantas veces.\n\nMartina recordó los entrenamientos: Elías llegaba pronto, repetía los tiros y escuchaba los consejos. Un marcador no mostraba todo ese trabajo.\n\nSe fueron a casa contentos, pero Martina sabía que el pase habría tenido sentido aunque el balón no hubiera entrado. Había elegido teniendo en cuenta al compañero y la situación, no una garantía de éxito.","q":[["¿Qué valoró Martina además de los goles anteriores?",["El esfuerzo y la buena posición de Elías","El color de sus botas","Que quedara mucho partido"],0],["¿Qué sugiere el final?",["Una decisión razonable no garantiza un resultado","Solo importan los goles","Nunca conviene pasar el balón"],0]]},{"id":"d64_es_4_16","grade":4,"t":"La luz que llegó de día","art":"sun","text":"Al anochecer, Elena encendió una lámpara en la pequeña casa del campo. Su padre le contó que parte de la energía se había recogido durante el día con paneles solares.\n\nEn los paneles, la luz permite generar corriente eléctrica. Una batería almacena energía para usarla más tarde. El sistema no guarda rayos de sol como si fueran objetos dentro de una caja.\n\nElena dibujó el recorrido desde el panel hasta la batería y la lámpara. Añadió flechas para no confundir los elementos.\n\nAfuera ya estaba oscuro, pero aquel dibujo unía la mañana con la noche. La tecnología le parecía menos misteriosa cuando podía seguir, paso a paso, qué hacía cada parte.","q":[["¿Qué función tenía la batería?",["Almacenar energía para después","Fabricar el sol","Guardar rayos como palitos"],0],["¿Para qué dibujó flechas?",["Para seguir el recorrido entre las partes","Para adornar sin explicar","Para cambiar la hora del día"],0]]},{"id":"d64_es_4_17","grade":4,"t":"El dragón panadero","art":"bread","text":"En un cuento del barrio vivía un dragón que soltaba un soplido caliente cuando se ponía nervioso. En el jardín eso daba problemas: las flores no agradecían tanto calor.\n\nLa panadera del cuento le propuso ayudar a mantener templada una gran sala de masas, siempre desde un lugar seguro preparado para él. El dragón aprendió a esperar la señal y a soplar con suavidad.\n\nEl personaje no tuvo que fingir que era otro animal. Necesitó comprender su fuerza, aprender a controlarla y encontrar una tarea adecuada.\n\nAl final de la historia, el barrio no lo admiraba por hacer mucho ruido. Lo apreciaba por su paciencia y por el pan que ayudaba a preparar cada mañana.","q":[["¿Qué tuvo que aprender el dragón?",["A controlar su fuerza y esperar la señal","A asustar a todos","A dejar de ser un personaje de cuento"],0],["¿Qué valoró el barrio?",["Su paciencia y su ayuda","La mayor llamarada","Que no volviera nunca"],0]]},{"id":"d64_es_4_18","grade":4,"t":"Las luces del fondo","art":"fish","text":"En el museo del mar, una sala mostraba animales que producen luz. El ambiente estaba oscuro y tranquilo. Sara descubrió que no toda la luz de los seres vivos sirve para lo mismo.\n\nSegún la especie, puede ayudar a atraer alimento, comunicarse o dificultar que otro animal distinga una silueta. Los paneles explicaban que la bioluminiscencia se produce mediante reacciones químicas, no por pequeñas bombillas.\n\nSara escogió un ejemplo para dibujarlo. Junto a él escribió su posible función en aquella especie, en vez de atribuírsela a todos los animales luminosos.\n\nAl salir, miró las lámparas del pasillo de otra manera. Una misma palabra, luz, podía aparecer en sistemas muy diferentes. Compararlos exigía fijarse tanto en las semejanzas como en las diferencias.","q":[["¿De dónde procede la bioluminiscencia?",["De reacciones químicas","De bombillas dentro de todos los peces","Del reflejo de un teléfono"],0],["¿Por qué Sara anotó la especie?",["La función de la luz podía variar","Todos los animales la usaban igual","Solo quería llenar el papel"],0]]},{"id":"d64_es_4_19","grade":4,"t":"El zumbido del puente","art":"bridge","text":"Cada tarde de viento, el pequeño puente del parque emitía un zumbido. Algunos vecinos inventaron una historia sobre un músico escondido. A Yago le divertía, pero quería una explicación comprobable.\n\nCon un adulto, escuchó desde la zona permitida y anotó cuándo aparecía el sonido. El personal del parque revisó la estructura. Una pieza de la barandilla vibraba cuando el viento llegaba desde cierta dirección.\n\nDespués del ajuste, el zumbido dejó de oírse. Yago guardó la leyenda en una página y la explicación en otra.\n\nPodía disfrutar de ambas sin confundirlas. Una era una invención compartida; la otra dependía de observaciones y de una revisión hecha por personas preparadas.","q":[["¿Qué causaba el zumbido?",["Una pieza que vibraba con el viento","Un músico dentro del agua","El dibujo de Yago"],0],["¿Cómo trató Yago la leyenda y la explicación?",["Las distinguió sin dejar de disfrutar la leyenda","Dijo que eran la misma prueba","Borró todas sus observaciones"],0]]},{"id":"d64_es_4_20","grade":4,"t":"El sendero del maizal","art":"leaf","text":"En una visita familiar, el sendero del maizal tenía varios cruces. Al regresar, Alma dudó sobre cuál habían tomado. Su tío se detuvo con ella en un lugar seguro, sin salir del camino.\n\nMiraron el plano de la entrada que él había fotografiado y localizaron una señal cercana. También preguntaron a una persona encargada, que confirmó la dirección de salida.\n\nMás tarde, Alma dibujó un mapa sencillo del paseo. Marcó referencias que la habían ayudado, no cada hoja del maíz.\n\nLa pequeña duda no arruinó la tarde. Le enseñó que pedir orientación puede formar parte de disfrutar una excursión. No hacía falta convertir un error de camino en una carrera para demostrar que sabía volver sola.","q":[["¿Qué hicieron cuando dudaron?",["Pararse, revisar referencias y pedir orientación","Salir corriendo entre las plantas","Separarse para buscar"],0],["¿Qué incluyó Alma en su mapa?",["Referencias útiles del recorrido","Cada hoja del maíz","Solo el color de los zapatos"],0]]},{"id":"d64_es_5_01","grade":5,"t":"El espacio que no estaba vacío","art":"book","text":"Al retirar una estantería de la biblioteca, quedó un hueco junto a la ventana. El grupo de mejoras propuso enseguida una vitrina, un armario y una mesa de juegos. Salma pidió esperar un mes antes de llenarlo.\n\nNo se trataba de olvidarlo. Propuso observar cómo se utilizaba, sin registrar nombres ni fotografiar a los visitantes. Una persona con andador podía girar allí con comodidad. Unos niños extendían un mapa grande en el suelo. En días de lluvia, el hueco servía para secarse antes de sentarse.\n\nLas observaciones no resolvían todas las necesidades, pero mostraban que el espacio libre ya cumplía funciones. Eligieron una mesa pequeña que pudiera moverse y conservaron una zona despejada.\n\nSalma aprendió que una buena propuesta no siempre añade objetos. A veces protege posibilidades que un plano lleno de muebles hace difíciles de imaginar.","q":[["¿Para qué pidió Salma un mes de espera?",["Para observar usos antes de decidir","Para evitar cualquier mejora","Para averiguar los nombres de todos"],0],["¿Qué reveló la observación?",["El espacio libre ya era útil","Solo servía para un armario","No se podía mover ningún mueble"],0]]},{"id":"d64_es_5_02","grade":5,"t":"Los nombres de la manta","art":"bow","text":"Una manta tejida llevaba una etiqueta con tres nombres. Abril supuso que correspondían a sus antiguos dueños. Su tía reconoció uno: el de la persona que había hilado la lana.\n\nConsultaron a una asociación de artesanos. Una integrante identificó los otros nombres, pertenecientes a quien había teñido el hilo y a quien lo había tejido. La etiqueta conservaba un registro del trabajo, no una lista de propietarios.\n\nAbril había pensado cambiar el papel gastado por otro limpio. Finalmente, lo fotografió para el álbum y lo protegió con un bolsillo de tela que dejaba visible la escritura. Añadió una nota nueva con lo aprendido y con las dudas que todavía quedaban.\n\nLa manta abrigaba igual que antes. Lo que había cambiado era su manera de comprenderla. Ahora, cada vez que la extendía, podía reconocer el trabajo de personas cuya aportación habría sido fácil pasar por alto.","q":[["¿Qué registraban los nombres?",["Distintas tareas de elaboración","Tres antiguos animales de la familia","Los precios de la manta"],0],["¿Por qué anotó también las dudas?",["Para no presentar suposiciones como hechos seguros","Para inventar una leyenda","Para sustituir la etiqueta original"],0]]},{"id":"d64_es_5_03","grade":5,"t":"La orilla no era una línea","art":"leaf","text":"El primer plano del sendero del estanque dibujaba un recorrido pegado al agua. Era corto y requería poca grava. Al recorrer la zona con una naturalista, Mauro descubrió un problema: la orilla cambiaba.\n\nDespués de la lluvia, el agua alcanzaba parte de la hierba. En periodos secos aparecía barro donde el dibujo suponía un borde firme. Entre ciertas plantas se refugiaban ranas y otros animales pequeños.\n\nEl grupo añadió al plano observaciones de distintas estaciones. La nueva ruta se alejaba del agua en algunos puntos. Una pasarela corta permitía cruzar una zona húmeda sin rellenarla con piedras.\n\nEl camino resultó algo más largo, pero respondía mejor al lugar. Mauro guardó ambos planos. Compararlos mostraba cómo una línea ordenada sobre el papel podía transformarse en una decisión que tuviera en cuenta el tiempo, el suelo y a otros seres vivos.","q":[["¿Qué daba por supuesto el primer plano?",["Que la orilla permanecía fija","Que el estanque no tenía agua","Que la grava se convertiría en hierba"],0],["¿Qué mejoró el recorrido revisado?",["Respetó zonas húmedas y refugios","Eliminó todas las plantas","Obligó a pasar por el barro"],0]]},{"id":"d64_es_5_04","grade":5,"t":"El sonido de una máquina","art":"ear","text":"El archivo del barrio pidió grabaciones de sonidos cotidianos. Candela pensó en el campanario y en una fiesta. Su abuelo sugirió el clic suave de su máquina de coser.\n\nAntes de grabar, acordaron qué querían compartir. Él escuchó el resultado y aprobó la versión final. Candela añadió la fecha, el modelo de la máquina y una breve explicación sobre las prendas que había ayudado a reparar. Eliminó una conversación privada que se había colado de fondo.\n\nDurante la exposición, varias personas reconocieron un sonido que ya no se oía en sus casas. Surgieron recuerdos de abrigos remendados y cortinas hechas con telas guardadas.\n\nCandela comprendió que conservar un sonido también exige cuidar su contexto y a las personas que aparecen alrededor. Un archivo puede proteger una memoria sin apropiarse de todo lo que el micrófono alcanza por casualidad.","q":[["¿Por qué eliminó la conversación del fondo?",["No estaba destinada a compartirse","Era la parte más antigua del audio","La máquina no había funcionado"],0],["¿Qué ayudaba a comprender la grabación?",["El contexto, la fecha y la explicación del abuelo","Solo un número de archivo","Una historia inventada sin permiso"],0]]},{"id":"d64_es_5_05","grade":5,"t":"Dos veces más rápido","art":"science","text":"Un anuncio de compostadores prometía obtener compost el doble de rápido. Al consejo escolar le pareció una ventaja evidente. Inés preguntó con qué se había comparado el producto.\n\nEl anuncio no indicaba la temperatura, los ingredientes ni la frecuencia con que se removía el material. La persona encargada del huerto explicó que esas condiciones podían afectar tanto al proceso como el recipiente.\n\nEl consejo no acusó a la empresa de engañar. Solicitó más información y preparó una lista de necesidades propias: acceso seguro, resistencia, coste y capacidad adecuada para sus voluntarios. También visitó dos huertos que usaban modelos diferentes.\n\nLa elección final no se apoyó en la frase más llamativa, sino en datos pertinentes para su escuela. Inés dejó escrito el razonamiento para que el siguiente consejo no heredara únicamente una compra, sino también una explicación que pudiera revisar.","q":[["¿Por qué era difícil valorar la promesa?",["Faltaban las condiciones de la comparación","El compost nunca cambiaba","No existían huertos escolares"],0],["¿Qué buscó el consejo?",["Datos útiles para sus necesidades concretas","Solo el anuncio más grande","Un resultado decidido de antemano"],0]]},{"id":"d64_es_5_06","grade":5,"t":"El recorrido de los faroles","art":"lamp","text":"La caminata del barrio se decoraba con faroles de papel y luces de pilas. El grupo de Adrián probó la ruta al anochecer, a la misma hora en que la usarían las familias.\n\nEn el plano parecía sencilla. Sin embargo, un escalón se confundía con el suelo, una señal miraba hacia la dirección equivocada y el lugar más tranquilo no dejaba espacio suficiente para girar con una silla de ruedas.\n\nTrabajaron con la organización para corregir esos detalles. Marcaron el escalón, orientaron la señal y apartaron un expositor. No añadieron más luz a todas partes: la dirigieron donde ayudaba.\n\nDurante la caminata, Adrián observó que la gente podía disfrutar de los faroles sin estar pendiente de obstáculos. Parte del valor de la planificación estaba precisamente en aquello que nadie tendría que sufrir ni notar. Una mejora puede ser importante aunque no se convierta en el centro de la atención.","q":[["¿Por qué probaron la ruta de noche?",["Las condiciones eran distintas a las del día","Los planos solo funcionaban sin sol","Las luces necesitaban estrellas"],0],["¿Cuál era el propósito de los cambios?",["Facilitar un recorrido claro y accesible","Crear la calle más brillante","Evitar que alguien se detuviera"],0]]},{"id":"d64_es_5_07","grade":5,"t":"La carta que no salió","art":"paper","text":"En una caja familiar, Julia encontró una carta que su bisabuela nunca había enviado. Describía un enfado con una amiga y terminaba a mitad de una idea. Julia pensó que sería la parte más interesante de su exposición escolar.\n\nSu madre le pidió considerar qué podían deducir realmente. No sabían por qué la carta había quedado guardada ni cómo había continuado la amistad. Un borrador privado no era necesariamente una declaración que su autora quisiera hacer pública.\n\nJulia cambió el enfoque de la exposición. Comparó lo que podían contar una lista de compras, una postal y una fotografía, sin mostrar la carta personal ni nombrar a la amiga.\n\nConservar la intimidad no hacía menos honesto su trabajo. Le permitía reconocer los límites de las fuentes. Había aprendido algo más valioso que un detalle llamativo: encontrar un documento no nos da permiso automático para contar toda la vida de otra persona.","q":[["¿Por qué era incierto interpretar la carta?",["Faltaban su propósito final y el contexto posterior","No tenía suficientes sellos","Todo borrador era público"],0],["¿Qué decidió Julia?",["Explicar los límites sin exponer los detalles privados","Inventar el final","Enviar la carta antigua a su clase"],0]]},{"id":"d64_es_5_08","grade":5,"t":"La reparación a la vista","art":"wood","text":"Una grieta atravesaba la mesa del centro social. Algunas personas querían sustituirla. Otras recordaban muchas reuniones alrededor de ella. Antes de elegir, pidieron a una carpintera que la examinara.\n\nLa profesional explicó que podía repararse con seguridad mediante una unión reforzada y una pieza de otra madera. El contraste quedaría visible. No fingiría que la grieta nunca había existido.\n\nRubén preparó para el tablón un resumen del proceso: la valoración de la carpintera, los materiales y las razones de la decisión. Conservar un objeto no era siempre la mejor opción; en este caso habían comprobado que era útil y viable.\n\nEn la siguiente reunión, la gente notó la superficie lisa de la pieza nueva. La mesa tenía otra historia sin perder su función anterior. Seguía ofreciendo un lugar donde acercar sillas y dedicar tiempo a los demás.","q":[["¿Por qué consultaron primero a una profesional?",["Para valorar seguridad y viabilidad","Para buscar un nombre para la grieta","Para aumentar el daño"],0],["¿Qué mostraba la madera diferente?",["La historia de la reparación","Que la mesa nunca se había roto","Un lugar que nadie podía usar"],0]]},{"id":"d64_es_5_09","grade":5,"t":"La segunda prueba","art":"science","text":"La clase de Elia comparó dos formas de mantener húmedos unos semilleros. Los primeros datos parecían favorecer una cubierta de tela. Antes de anunciar el resultado, revisaron sus apuntes.\n\nUna bandeja había estado más cerca del radiador. Además, durante dos días se habían usado recipientes distintos para medir el agua. Cualquiera de esas diferencias podía influir en la rapidez con que se secaba la tierra.\n\nLa clase redactó una conclusión provisional: la prueba planteaba una pregunta interesante, pero aún no permitía una comparación justa. Organizaron otra con posiciones equivalentes y una forma común de medir.\n\nElia quería colgar una respuesta clara en la pared. Terminó mostrando el primer intento junto al plan revisado. Aquello también era conocimiento: descubrir una debilidad en el procedimiento ayudaba a que el siguiente resultado mereciera más confianza. Aprender no siempre significa obtener de inmediato la respuesta que esperábamos.","q":[["¿Qué debilitaba la primera comparación?",["Diferencias de posición y de medición","Que hubieran tomado apuntes","Que las semillas necesitaran agua"],0],["¿Qué buscaba la segunda prueba?",["Mantener constantes condiciones importantes","Asegurar que ganara la tela","Evitar cualquier medida"],0]]},{"id":"d64_es_5_10","grade":5,"t":"El banco de la tarde","art":"sunrise","text":"El banco del patio miraba hacia una pared. Cuando se pidieron ideas para mejorarlo, varias personas propusieron un mural. Leandro sugirió orientarlo hacia el cielo del atardecer.\n\nAntes de mover una pieza tan pesada, probaron con sillas. Comprobaron el deslumbramiento, el espacio de paso y la vista desde distintas alturas. Una vecina explicó que prefería el rincón resguardado los días de viento.\n\nLa solución no fue idéntica al primer dibujo. Giraron el banco solo un poco y dejaron un asiento menor junto a la pared. Así podían elegir entre dos ambientes.\n\nAl estrenarlo no ocurrió nada espectacular. La gente se sentó, observó las nubes rosadas y permaneció allí unos minutos más. Leandro consideró que era un buen resultado. Un lugar compartido se había vuelto más acogedor sin necesitar más ruido, más objetos ni una única manera correcta de disfrutarlo.","q":[["¿Para qué ensayaron con sillas?",["Para valorar los efectos antes de mover el banco","Para no escuchar a la vecina","Para cambiar el tiempo"],0],["¿Qué influyó en la decisión final?",["Las observaciones y necesidades de varias personas","Solo el primer dibujo","La obligación de mirar todos al oeste"],0]]},{"id":"d64_es_5_11","grade":5,"t":"La libreta del cielo","art":"star","text":"Desde el patio, con una persona adulta a su lado, Lidia observaba la misma zona del cielo cada noche despejada. No pretendía contar todas las estrellas. Anotaba posiciones y dibujaba lo que alcanzaba a distinguir.\n\nUna tarde apareció una mancha tenue que no recordaba. En vez de anunciar un descubrimiento, revisó sus apuntes y comparó mapas del cielo. Su tío la ayudó a consultar a una asociación de astronomía. Era un objeto conocido que ahora resultaba más fácil de ver desde allí.\n\nLidia no sintió que su cuaderno hubiera perdido valor. Le había permitido formular una pregunta concreta y buscar una respuesta comprobable. La observación seguía siendo suya aunque el objeto ya tuviera nombre.\n\nAl guardar el telescopio, dejó un espacio para la próxima noche. La curiosidad no necesitaba un premio ni una primicia para encontrar motivos por los que volver a mirar.","q":[["¿Por qué revisó sus notas antes de anunciar nada?",["Para comprobar lo que realmente había observado","Para inventar una estrella nueva","Para borrar las noches anteriores"],0],["¿Qué valor conservaba el cuaderno?",["Ayudaba a preguntar y comparar con cuidado","Solo valía si descubría algo desconocido","Sustituía todos los mapas del cielo"],0]]},{"id":"d64_es_5_12","grade":5,"t":"El mapa que fue cambiando","art":"home","text":"Cuando Amira llegó al barrio, dibujó un mapa sin nombres: una panadería, un portal amarillo, un parque con un banco curvo. Reconocía las formas, pero todavía no conocía a las personas.\n\nCada semana añadía un detalle después de una conversación. La panadera se llamaba Rosa y guardaba las cajas pequeñas para quien las necesitara. El hombre del banco estaba aprendiendo a dibujar árboles. La vecina del portal amarillo cuidaba las plantas durante las vacaciones de otros.\n\nEn invierno, el mapa tenía tantas notas que Amira necesitó otra hoja. El barrio no se había transformado por completo. Había cambiado la relación que ella tenía con él.\n\nConservó el primer dibujo junto al nuevo. Le recordaba que conocer un lugar puede consistir tanto en aprender sus caminos como en descubrir quién comparte con nosotros las tareas y los pequeños ratos de cada día.","q":[["¿Qué fue añadiendo Amira?",["Nombres y detalles de las personas","Calles que no existían","Solo números de autobús"],0],["¿Qué había cambiado sobre todo?",["Su relación con el barrio","La ubicación de cada edificio","El tamaño de todas las casas"],0]]},{"id":"d64_es_5_13","grade":5,"t":"Las señales y la intimidad","art":"wifi","text":"En un taller, Joel supo que las señales de radio pueden reflejarse en objetos y personas. Al cambiar una habitación, también puede cambiar el patrón de esas reflexiones. Algunos investigadores estudian cómo aprovecharlas para detectar movimientos.\n\nLa demostración no utilizaba una cámara. Aun así, Joel se preguntó si las personas observadas sabrían que un sistema podía obtener información sobre ellas. La ausencia de una imagen no significaba automáticamente ausencia de datos personales.\n\nLa clase preparó dos listas: posibles usos útiles y condiciones necesarias para respetar la intimidad. Incluyeron información clara, consentimiento cuando correspondiera, límites de uso y medidas para proteger los datos.\n\nJoel salió sin una respuesta sencilla que sirviera para todos los casos. Sí llevaba una pregunta mejor: no solo qué puede hacer una tecnología, sino quién decide cuándo debe hacerlo y cómo puede una persona conservar el control sobre su propia información.","q":[["¿Qué comprendió Joel sobre no usar cámaras?",["También podía obtenerse información personal","No podía existir ningún problema de privacidad","Las señales dejaban de moverse"],0],["¿Qué añadió la clase a los usos posibles?",["Condiciones para proteger a las personas","Una lista de contraseñas ajenas","Una promesa de usarlo siempre"],0]]},{"id":"d64_es_5_14","grade":5,"t":"La última parada de Clara","art":"bus","text":"Durante muchos años, Clara condujo la biblioteca ambulante por pueblos donde no había una biblioteca fija. En su última jornada esperaba una despedida discreta. Había preferido seguir con el horario de siempre.\n\nEn la parada final encontró a varias familias con libros en las manos. No eran regalos nuevos: cada persona llevaba un ejemplar que recordaba haber leído gracias a aquel servicio. Un maestro mostró un álbum que conoció de niño. Una mujer habló de las novelas que la acompañaban mientras cuidaba a su padre.\n\nClara escuchó historias que nunca habían aparecido en las cifras del préstamo mensual. Los números eran necesarios para organizar el trabajo, pero no contenían todo su significado.\n\nAl cerrar el vehículo, no sintió que los años quedaran guardados dentro. Parte de lo que había hecho seguía viajando en la memoria y en las lecturas de otras personas.","q":[["¿Qué llevaban las familias?",["Libros relacionados con recuerdos del servicio","Vehículos nuevos","Solo listas de multas"],0],["¿Qué mostraron las despedidas?",["Un valor que las cifras no describían por completo","Que las cifras eran siempre inútiles","Que nadie había leído los libros"],0]]},{"id":"d64_es_5_15","grade":5,"t":"Oscuridad para observar","art":"moon","text":"Desde el balcón, Paula solo distinguía unas pocas estrellas. En una visita organizada a un observatorio de montaña vio muchas más. Su monitor explicó que no bastaba con tener un telescopio grande.\n\nLa atmósfera puede distorsionar la luz que llega de lejos. A mayor altura, parte del aire queda por debajo del instrumento. La luz artificial que se dispersa desde las poblaciones también dificulta ver objetos débiles.\n\nAl volver, Paula investigó luminarias que orientaban la luz hacia el suelo. No proponía dejar las calles inseguras ni apagar cualquier iluminación sin pensar. Quería conocer maneras de iluminar lo necesario y reducir lo que se escapaba al cielo.\n\nPreparó un dibujo con dos tipos de farolas y sus haces. La diferencia era una invitación a diseñar mejor, no a elegir entre personas y estrellas. Cuidar un entorno también puede significar dirigir con más atención algo tan cotidiano como la luz.","q":[["¿Qué favorecía la observación en la montaña?",["Menos aire por encima y un cielo más oscuro","Que allí no existiera atmósfera","Que las estrellas fueran mayores"],0],["¿Qué buscaba Paula al estudiar las farolas?",["Iluminar lo necesario sin tanta dispersión","Eliminar toda seguridad nocturna","Aumentar el brillo del cielo"],0]]},{"id":"d64_es_5_16","grade":5,"t":"Lo que lleva el río","art":"waves","text":"En una lectura de poesía, el río parecía recordar la montaña donde había nacido. Guardaba sequías, crecidas, una hoja y el reflejo de un puente. Ada sabía que un río no tiene memoria como una persona.\n\nSu profesora les invitó a observar qué permitía expresar aquella imagen. El agua transportaba materiales de lugares distintos; el paisaje conservaba marcas de procesos anteriores. La voz del poema unía esos hechos con la experiencia de alguien que se aleja de su hogar.\n\nAda escribió unas líneas sobre lo que quería llevar consigo al cambiar de escuela: una amistad, una canción familiar y la costumbre de preguntar cuando no entendía. No necesitaba meter nada de eso en una maleta.\n\nAl terminar, volvió al poema. Comprendió que una comparación puede ser valiosa sin funcionar como una explicación literal. A veces ofrece una manera tranquila de pensar en un cambio que todavía no sabemos describir.","q":[["¿Cómo debe entenderse el río que recuerda?",["Como una imagen poética","Como una persona escondida","Como una afirmación literal sobre su cerebro"],0],["¿Para qué le sirvió la imagen a Ada?",["Para pensar qué conservar durante un cambio","Para demostrar que el agua escribe","Para evitar cambiar de escuela"],0]]},{"id":"d64_es_5_17","grade":5,"t":"Un planeta que no se ve","art":"planet","text":"En el club de astronomía, Daniel aprendió que algunos planetas se detectan sin obtener una fotografía directa. Si un planeta pasa por delante de su estrella desde nuestro punto de vista, puede producir una pequeña disminución de brillo.\n\nUna bajada aislada no basta para concluir que hay un planeta. Los investigadores buscan repeticiones y examinan otras explicaciones posibles. Después comparan resultados con métodos y observaciones adicionales.\n\nDaniel dibujó una gráfica sencilla, pero evitó poner Planeta descubierto sobre el primer descenso. Escribió Posible señal para investigar.\n\nLe sorprendió la paciencia que podía haber detrás de una noticia breve. Un titular anunciaba un hallazgo; el trabajo incluía esperar, revisar y descartar. Aquella noche no encontró un mundo nuevo con su pequeño telescopio. Aun así, mirar la estrella le pareció distinto: sabía un poco más sobre las preguntas que otras personas estaban aprendiendo a hacerle a su luz.","q":[["¿Qué puede indicar una bajada repetida de brillo?",["Un posible paso de un planeta","Que la estrella se apaga cada noche","Que hay una nube dentro del telescopio"],0],["¿Por qué no basta un descenso aislado?",["Hay otras explicaciones que revisar","Las gráficas no sirven","Un planeta debe tener nombre antes"],0]]},{"id":"d64_es_5_18","grade":5,"t":"La pregunta de la pantalla","art":"picture","text":"En una exposición sobre inventos, Lara vio los bocetos de un joven que había intentado transmitir imágenes mediante electricidad. Sus ideas no surgían de una sola máquina terminada, sino de preguntas, ensayos y conocimientos aprendidos de otras personas.\n\nLara había imaginado a los inventores trabajando siempre solos y acertando a la primera. Los cuadernos mostraban cambios de dirección, cálculos y colaboraciones. También aparecían debates sobre quién había aportado cada avance.\n\nPara su trabajo de clase, eligió contar el proceso en vez de presentar un héroe que lo había resuelto todo de golpe. Separó lo que mostraban los documentos de las anécdotas que no había podido confirmar.\n\nCuando encendió la pantalla de casa, pensó en todas las decisiones que quedaban ocultas detrás de un gesto tan sencillo. Comprender un invento no le quitaba encanto. Le permitía reconocer más trabajo del que se ve en el objeto acabado.","q":[["¿Qué cambió en la idea de Lara sobre inventar?",["Reconoció ensayos, cambios y colaboración","Creyó que siempre ocurre sin aprender","Pensó que nadie anota ideas"],0],["¿Qué decidió destacar en su trabajo?",["El proceso y las fuentes disponibles","Una anécdota que no podía comprobar como si fuera cierta","Solo el tamaño de la pantalla"],0]]},{"id":"d64_es_5_19","grade":5,"t":"La página que susurraba","art":"book","text":"Cada tarde, cerca de una estantería de la biblioteca, se oía un roce breve. Algunas personas inventaron la historia de un libro que susurraba. A Nuria le gustaba el cuento, aunque quería saber qué provocaba el sonido real.\n\nCon la bibliotecaria, observó cuándo aparecía. Coincidía con la apertura de una ventana alta. La corriente levantaba la esquina de una lámina suelta que rozaba el marco de un expositor.\n\nSujetaron la lámina con un soporte adecuado. El ruido cesó, pero la historia no tuvo que desaparecer. Nuria la escribió en una hoja para el rincón de relatos inventados y añadió otra ficha con la explicación de la investigación.\n\nAmbas podían convivir si estaban bien identificadas. La biblioteca tenía espacio para imaginar y para comprobar. Saber de dónde venía el roce le permitía disfrutar del pequeño misterio sin sentir que cada sonido desconocido debía convertirse en una amenaza.","q":[["¿Qué producía el sonido?",["Una lámina movida por la corriente","Un libro que hablaba de verdad","Una persona escondida tras el muro"],0],["¿Cómo conservó Nuria las dos versiones?",["Distinguió el cuento de la explicación comprobada","Presentó ambas como hechos idénticos","Ocultó lo que habían descubierto"],0]]},{"id":"d64_es_5_20","grade":5,"t":"La alfombra y el robot","art":"game","text":"El robot aspirador de la sala común se detenía siempre en la misma alfombra. En el grupo de mensajes, algunas personas propusieron cambiar el aparato. Otras decían que bastaba con quitar cualquier cosa que lo confundiera.\n\nAntes de decidir, Tomás observó varias pasadas con la persona responsable. El borde de la alfombra se doblaba al recibir el primer empujón. No era un obstáculo constante: aparecía durante el movimiento. Un adulto colocó una base antideslizante apropiada y comprobó que el paso quedaba seguro para todos, no solo para la máquina.\n\nTomás escribió un mensaje breve explicando el problema y el arreglo. Evitó decir que el robot era inteligente o torpe como una persona. Describió lo que hacía en aquellas condiciones.\n\nLa sala conservó su alfombra y el aparato pudo continuar. La solución había comenzado al cambiar una discusión sobre etiquetas por una observación concreta de cómo se encontraban dos objetos cotidianos.","q":[["¿Cuándo aparecía el obstáculo?",["Cuando el robot doblaba el borde","Solo con la sala vacía","Cuando alguien escribía un mensaje"],0],["¿Qué hizo más útil la conversación?",["Describir condiciones y comprobar una solución","Poner más etiquetas al robot","Elegir un culpable antes de observar"],0]]}]};
